ATL_SRC.push(['@atl/forms/archive.js', 0, `// Sent-reports archive (#/archive): a copy of every report the app sends — the email (recipients, subject, message)
// and each attachment — filed by Report → year → month.
// Reports: Electrolit Monthly Report (filed under the report month), Late / Call Out / Left Early Forms (week-ending
// month), Safety Incident Reports — OSHA (incident month), OTIF Incident Reports (incident month).
// Entries live in "archive"; attachments in "archiveFiles", split into ~700 KB parts (Firestore allows ~1 MB per
// document). Demo Mode keeps the parts in this browser's IndexedDB. Sending the same report on the same day again
// replaces that day's copy instead of adding a duplicate.
import { store } from '@atl/store.js';
import { todayISO, toast, downloadBlob } from '@atl/util.js';
import { emlDraft } from '@atl/forms/email.js';

export const REPORTS = {
  elxMonthly: 'Electrolit Monthly Report',
  wrMonthly: 'Smurfit WestRock Monthly Report',
  kpiMonthly: 'Building Monthly KPI Report',
  calloff: 'Late / Call Out / Left Early Forms',
  safety: 'Safety Incident Reports (OSHA)',
  otif: 'OTIF Incident Reports',
  writeup: 'Disciplinary Actions / Write-Ups',
};
// Disciplinary write-ups are confidential: kept in their own collections that only managers and admins can read
// (same as the Disciplinary Log).
export const CONFIDENTIAL = new Set(['writeup']);
const collOf = kind => (CONFIDENTIAL.has(kind) ? 'archiveHR' : 'archive');
const filesOf = kind => (CONFIDENTIAL.has(kind) ? 'archiveHRFiles' : 'archiveFiles');
/** The archive collections this user may read. */
export const archiveColls = () => ['archive', ...(store.can('confidential') ? ['archiveHR'] : [])];
export const allArchived = () => archiveColls().flatMap(c => store.rows(c).map(e => ({ ...e, _coll: c })));
const PART = 700000; // base64 characters per stored part
const slug = s => String(s || '').replace(/[^\\w-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const b64 = bytes => { let s = ''; for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000)); return btoa(s); };
const unb64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

// Demo Mode: parts in IndexedDB (localStorage is far too small for Word files and photos).
let dbp;
const db = () => (dbp ||= new Promise((res, rej) => {
  const r = indexedDB.open('atl-ops-archive', 1);
  r.onupgradeneeded = () => r.result.createObjectStore('parts', { keyPath: 'id' });
  r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
}));
const idb = async (mode, fn) => { const d = await db(); return new Promise((res, rej) => { const t = d.transaction('parts', mode), q = fn(t.objectStore('parts')); t.oncomplete = () => res(q?.result); t.onerror = () => rej(t.error); }); };

async function putParts(kind, archiveId, files) {
  const meta = [];
  for (const [fi, [name, bytes, type]] of files.entries()) {
    const s = b64(bytes), n = Math.max(1, Math.ceil(s.length / PART));
    for (let p = 0; p < n; p++) {
      const doc = { archiveId, file: fi, part: p, data: s.slice(p * PART, (p + 1) * PART) };
      if (store.demo) await idb('readwrite', o => o.put({ id: \`\${archiveId}|\${fi}|\${p}\`, ...doc }));
      else await store.set(filesOf(kind), \`\${archiveId}__\${fi}_\${p}\`, doc);
    }
    meta.push({ name, type, size: bytes.length, parts: n });
  }
  return meta;
}
async function dropParts(entry) {
  for (const [fi, f] of (entry.files || []).entries()) for (let p = 0; p < (f.parts || 1); p++) {
    if (store.demo) await idb('readwrite', o => o.delete(\`\${entry.id}|\${fi}|\${p}\`));
    else await store.remove(filesOf(entry.kind), \`\${entry.id}__\${fi}_\${p}\`).catch(() => {});
  }
}
/** An entry's attachments: [[name, Uint8Array, type]]. Parts are read one document at a time. */
export async function archiveFiles(entry) {
  const out = [];
  for (const [fi, f] of (entry.files || []).entries()) {
    let s = '';
    for (let p = 0; p < (f.parts || 1); p++) {
      const d = store.demo ? await idb('readonly', o => o.get(\`\${entry.id}|\${fi}|\${p}\`)) : await store.get(filesOf(entry.kind), \`\${entry.id}__\${fi}_\${p}\`);
      if (!d) throw new Error(\`Part of \${f.name} is missing from the archive.\`);
      s += d.data;
    }
    out.push([f.name, unb64(s), f.type]);
  }
  return out;
}

/** Building folder: '6021', '6049', 'Both' (a report covering both) or '' (not known). Accepts one value or a list. */
export function buildingOf(v) {
  const set = new Set([].concat(v ?? []).map(x => String(x ?? '').match(/60(21|49)/)?.[0]).filter(Boolean));
  return set.size > 1 ? 'Both' : [...set][0] || (String(v ?? '').toLowerCase() === 'both' ? 'Both' : '');
}
/** An employee's home building (for write-ups / attendance forms), by roster or labor name. */
export function employeeBuilding(name) {
  const n = String(name ?? '').trim().toUpperCase(), e = store.rows('employees').find(x => String(x.name ?? '').toUpperCase() === n || String(x.laborName ?? '').toUpperCase() === n);
  return e ? String(e.homeFacility || e.defaultBuilding || '') : '';
}
export const BUILDING_LABEL = { 6021: 'Building 6021', 6049: 'Building 6049', Both: 'Both buildings', '': 'Building not recorded' };

/**
 * Save a copy of a sent report. a.building: '6021' / '6049' / 'Both' (or a list of buildings) — the folder under the year. a: { kind (key of REPORTS), fileDate (ISO — decides the year / month folder), title,
 * subject, to, html (email message, '' for a file-only download), attachments: [[name, Uint8Array, type]], ref }
 * Never throws: a failure only shows a warning, so sending is never blocked.
 */
export async function archiveSent(a) {
  try {
    const date = /^\\d{4}-\\d\\d-\\d\\d$/.test(a.fileDate || '') ? a.fileDate : todayISO();
    const id = \`\${a.kind}_\${slug(a.ref || a.title)}_\${todayISO().replace(/-/g, '')}\`, coll = collOf(a.kind);
    await store.need([coll]);
    const old = store.rows(coll).find(e => e.id === id);
    if (old) await dropParts(old);
    const files = await putParts(a.kind, id, a.attachments || []);
    await store.set(coll, id, {
      kind: a.kind, report: REPORTS[a.kind] || a.kind, year: date.slice(0, 4), month: date.slice(5, 7), fileDate: date, building: buildingOf(a.building),
      title: a.title || a.subject || '', subject: a.subject || '', to: a.to || '', html: a.html || '', ref: a.ref || '',
      emailed: !!a.html, files, sentAt: new Date().toISOString(), sentBy: store.user?.name || store.user?.email || '',
    });
    return id;
  } catch (e) {
    console.warn('Archive copy not saved', e);
    toast(\`Sent, but the archive copy was not saved: \${e.message}\`, 'warn');
    return null;
  }
}

export async function removeArchived(entry) { await dropParts(entry); await store.remove(collOf(entry.kind), entry.id); }
/** Download one attachment. */
export async function downloadArchived(entry, i) { const [name, bytes, type] = (await archiveFiles(entry))[i]; downloadBlob(name, new Blob([bytes], { type })); }
/** Rebuild the email as an Outlook draft (to resend or forward). */
export async function reEmail(entry) {
  const atts = await archiveFiles(entry);
  const subject = entry.subject || entry.title;
  downloadBlob(\`\${subject.replace(/[\\\\/:*?"<>|]/g, '-')}.eml\`, emlDraft({ to: entry.to, subject, html: entry.html || \`<p>\${entry.title}</p>\`, attachments: atts }));
}`]);

