ATL_SRC.push(['@atl/forms/email.js', 0, `// Builds an unsent email (.eml) that Outlook opens as a new message, ready to send — subject, body and attachments
// filled in. "X-Unsent: 1" is what makes Outlook open it as a draft instead of a received message.

const B64_LINE = 76;
/** Uint8Array → base64, wrapped at 76 characters (MIME). */
function b64(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(new RegExp(\`.{1,\${B64_LINE}}\`, 'g'), '$&\\r\\n');
}
const utf8b64 = s => b64(new TextEncoder().encode(s));
/** Header words outside plain ASCII use RFC 2047 encoded-words. */
const hdr = s => (/^[\\x20-\\x7e]*$/.test(s) ? s : \`=?UTF-8?B?\${utf8b64(s).replace(/\\s/g, '')}?=\`);
/** Attachment names: keep them plain ASCII so every mail client shows them the same. */
const asciiName = s => s.replace(/[–—]/g, '-').replace(/[^\\x20-\\x7e]/g, '').replace(/"/g, "'");

/**
 * m: { to?, subject, html, attachments: [[fileName, Uint8Array, mimeType]] } → Blob (message/rfc822)
 */
export function emlDraft(m) {
  const boundary = 'atl-ops-' + Math.random().toString(36).slice(2);
  const parts = [
    \`To: \${m.to || ''}\`,
    \`Subject: \${hdr(m.subject)}\`,
    'X-Unsent: 1',
    'MIME-Version: 1.0',
    \`Content-Type: multipart/mixed; boundary="\${boundary}"\`,
    '',
    \`--\${boundary}\`,
    'Content-Type: text/html; charset="utf-8"',
    'Content-Transfer-Encoding: base64',
    '',
    utf8b64(m.html),
  ];
  for (const [name, bytes, type] of m.attachments) {
    const n = asciiName(name);
    parts.push(\`--\${boundary}\`, \`Content-Type: \${type}; name="\${n}"\`, 'Content-Transfer-Encoding: base64',
      \`Content-Disposition: attachment; filename="\${n}"\`, '', b64(bytes));
  }
  parts.push(\`--\${boundary}--\`, '');
  return new Blob([parts.join('\\r\\n')], { type: 'message/rfc822' });
}`]);

