import { SOP_DOCS, SOP_RULES } from '@atl/forms/sops.js';
import { POLICY_RULES } from '@atl/forms/policies.js';
import { LIBRARY } from '@atl/forms/library.js';

const STOP = new Set(('a an the and or of to in on at for with from by is are was were be been being it its this that these those he she they his her their him them i we you our your as not no do does did done has have had will would should could can may must into onto off up down out over under than then there here when while after before about all any each every other only also just very per via if but so such same own too more most some '
  + 'time times week weeks day days today yesterday morning shift employee operator associate always never').split(' '));
/** Crude stemmer: good enough to match "loading" with "load", "pedestrians" with "pedestrian". */
