// ===================== store.js =====================
ATL_SRC.push(['@atl/store.js', 0, `// Data + auth layer. Two backends with the same interface:
//   • Firebase (Firestore + Auth) when config.js has real values
//   • Demo (localStorage) when config.js still says REPLACE_ME, or the URL has ?demo
// Collections are loaded lazily with live listeners and cached in memory.

import { firebaseConfig } from '@atl/config.js';

const FB = 'https://www.gstatic.com/firebasejs/11.0.2/';
export const demo = firebaseConfig.apiKey === 'REPLACE_ME' || new URLSearchParams(location.search).has('demo');

/** Collections whose doc IDs are sequential refs (OTIF-0001 …). */
export const REF_PREFIX = { otif: 'OTIF', attendance: 'ATT', damage: 'DMG', discipline: 'DSC', incidents: 'INC', trucks: 'TRK' };

const cache = new Map();      // coll -> array of docs ({id, ...data})
const ready = new Map();      // coll -> Promise
const listeners = new Set();
let backend;

export const store = {
  demo,
  user: null,      // { uid, email, name }
  role: null,      // 'pending' | 'viewer' | 'supervisor' | 'manager' | 'admin'
  settings: null,  // config/settings doc
  rail: null,      // config/rail doc

  onChange(fn) { listeners.add(fn); return () => listeners.delete(fn); },
  rows(coll) { return cache.get(coll) || []; },

  /** Ensure collections are subscribed; resolves after first data arrives. */
  need(colls) {
    return Promise.all(colls.map(c => {
      if (!ready.has(c)) ready.set(c, backend.subscribe(c, docs => { cache.set(c, docs); emit(c); }));
      return ready.get(c);
    }));
  },

  async add(coll, data) {
    const prefix = REF_PREFIX[coll];
    if (prefix) return backend.addWithRef(coll, prefix, clean(data));
    return backend.add(coll, clean(data));
  },
  set: (coll, id, data) => backend.set(coll, id, clean(data)),
  /** Read one document once (without subscribing to the whole collection) — e.g. an archived file part. */
  get: (coll, id) => backend.get(coll, id),
  update: (coll, id, data) => backend.update(coll, id, clean(data)),
  remove: (coll, id) => backend.remove(coll, id),
  /** Replace a whole collection (used by the Excel importer). docs: [{id?, ...}] */
  replaceAll: (coll, docs, onProgress) => backend.replaceAll(coll, docs, onProgress),
  /** Write many docs: {id?, ...data} upserts (or adds when no id); {_delete: id} deletes. */
  writeMany: (coll, docs) => backend.writeMany(coll, docs),
  saveConfig: async (name, data) => { await backend.set('config', name, clean(data)); },

  // auth
  signInGoogle: () => backend.signInProvider('google'),
  signInMicrosoft: () => backend.signInProvider('microsoft'),
  signInEmail: (e, p) => backend.signInEmail(e, p),
  signUpEmail: (e, p) => backend.signUpEmail(e, p),
  resetPassword: e => backend.resetPassword(e),
  signOut: () => backend.signOut(),
  listUsers: () => backend.listUsers(),
  setUserRole: (uid, role) => backend.set('users', uid, { role }, true),

  can(action) {
    const r = this.role;
    const lvl = { pending: 0, viewer: 1, supervisor: 2, manager: 3, admin: 4 }[r] ?? 0;
    return { view: lvl >= 1, edit: lvl >= 2, delete: lvl >= 3, confidential: lvl >= 3, admin: lvl >= 4 }[action];
  },
};

function emit(coll) { for (const fn of listeners) fn(coll); }
function clean(o) {
  const out = {};
  for (const [k, v] of Object.entries(o)) if (k !== 'id' && v !== undefined) out[k] = v;
  return out;
}

/** Boot: resolves the auth state via callback(user|null). Loads config docs once signed in. */
export async function boot(onAuth) {
  backend = demo ? demoBackend() : await firebaseBackend();
  backend.onAuth(async user => {
    store.user = user;
    store.role = user ? await backend.ensureUserDoc(user) : null;
    if (user && store.can('view')) await loadConfig();
    onAuth(user);
  });
}

async function loadConfig() {
  let gotS = false, gotR = false;
  await new Promise(res => {
    const check = () => { if (gotS && gotR) res(); };
    backend.watchDoc('config', 'settings', d => { store.settings = withDefaults(d); if (!gotS) { gotS = true; check(); } emit('config'); });
    backend.watchDoc('config', 'rail', d => { store.rail = withRailDefaults(d); if (!gotR) { gotR = true; check(); } emit('config'); });
  });
}

// ---------- defaults (used until the Excel import / Settings page fills them) ----------
export function withDefaults(d = {}) {
  const lists = {
    incidentCategories: ['Mispick', 'Mis-Ship', 'Missed Delivery', 'Trailer Number', 'Paperwork', 'Process', 'Inventory', 'Inbound Discrepancy', 'Communication', 'Damage', 'Safety'],
    customers: ['WestRock', 'Electrolit', 'Catalyst', 'Twin Rivers', 'UPM', 'IPG', 'Domtar', 'Maxxon', 'Not Recorded'],
    facilities: ['6021', '6049'],
    supervisors: [],
    incidentStatus: ['Open', 'In Progress', 'Closed'],
    awardTypes: ['Perfect Attendance', 'Employee of the Month', 'Safety / SOP Quiz'],
    rosterStatus: ['Active', 'Not on Current Roster'],
    damageStage: ['Inbound', 'Outbound', 'In Storage', 'Handling / Moves', 'Rail Car', 'Other'],
    damageType: ['Crushed / Dented', 'Torn / Punctured Wrap', 'Clamp / Tine Damage', 'Water / Wet', 'Dropped / Fallen', 'Contaminated', 'Core Damage', 'Pallet Failure', 'Radial Damage', 'Outer Laps Damage', 'Other'],
    damageCause: ['Operator Error', 'Equipment Failure', 'Improper Stacking / Storage', 'Carrier / Trailer', 'Rail Car / Railroad', 'Shipper / Mill Packaging', 'Weather / Roof Leak', 'Unknown'],
    damageResponsible: ['Piper', 'Carrier', 'Railroad', 'Shipper / Mill', 'Customer', 'Unknown'],
    // Damage Log ▸ Recorded By: customers who report damage themselves, listed after the supervisors.
    damageRecordedBy: ['Westrock', 'UPM', 'Catalyst', 'IPG', 'Electrolit'],
    damageUnit: ['Rolls', 'Pallets', 'Cases', 'Units', 'Tons', 'Lbs'],
    claimStatus: ['Not Filed', 'Open', 'Filed', 'Approved', 'Denied', 'Closed'],
    disciplineCategories: ['Attendance', 'Safety', 'Food Safety / SQF', 'Quality / Mispick', 'Conduct / Behavior', 'Policy / SOP Violation', 'Insubordination', 'Equipment / Property Damage', 'Other'],
    disciplineActions: ['Documented Coaching', 'Verbal Warning', 'Written Warning', 'Final Written Warning', 'Suspension', 'Termination'],
    ...(d.lists || {}),
  };
  return {
    reportingYear: new Date().getFullYear(),
    defaultShiftStart: '07:50',
    // Manager each building's employees report to (used when an employee has no Reports To of their own).
    manager6021: 'Shafton Clark',
    manager6049: 'Luke Piper',
    orderAccuracyTarget: 0.99,
    attendanceTarget: 0.95,
    disciplineMonths: 12,
    salariedHours: 40,
    damageTarget6049: null,
    damageTarget6021: null,
    // Labor productivity (P&L Dashboard ▸ Settings C21–C32): 6049 pallets / hr, 6021 tons / hr. "Op" = operator
    // hours only (w/o clerical), "All" = every hour (w/ clerical). On Target at or above the target, Close at or
    // above the close threshold, Below under it.
    prodTargetOp6049: 17, prodCloseOp6049: 14, prodTargetAll6049: 17, prodCloseAll6049: 14,
    prodTargetOp6021: 16, prodCloseOp6021: 12, prodTargetAll6021: 16, prodCloseAll6021: 12,
    // Display-only thresholds (Visual Redesign, Nov 2026): grey on the individual OT chart under this many regular
    // hours; Attendance Scorecard cards: Watch at 5+ and Coaching now at 10+ occurrences in the last 90 days.
    otMinRegHours: 200, scWatch90: 5, scCoach90: 10,
    // Safety Incident reports: who the Outlook email is addressed to (remembered from the form).
    safetyEmailTo: '',
    otifEmailTo: '',
    throughputCustomers: [],
    hrCounters: [
      { counter: 'Regular', countsAs: 'Regular' },
      { counter: 'Overtime', countsAs: 'OT' },
      { counter: '_FLSA Overtime', countsAs: 'Ignore' },
    ],
    ...d,
    lists: { ...lists, damageType: withDamageTypes(lists.damageType) },
    incidentTypes: withRecordable(d.incidentTypes || DEFAULT_TYPES),
  };
}
// Damage Log ▸ Damage Type: these are always offered (Nov 2026, from Josh), also after a workbook import or a Settings
// edit replaces the list. They go in before "Other"; the existing types stay.
const DAMAGE_TYPES_ADDED = ['Leak', 'Crushed', 'Torn Wrapper', 'Aesthetically Unsellable'];
function withDamageTypes(list = []) {
  const have = new Set(list.map(t => String(t).trim().toLowerCase()));
  const add = DAMAGE_TYPES_ADDED.filter(t => !have.has(t.toLowerCase()));
  if (!add.length) return list;
  const i = list.findIndex(t => String(t).trim().toLowerCase() === 'other');
  return i < 0 ? [...list, ...add] : [...list.slice(0, i), ...add, ...list.slice(i)];
}
const DEFAULT_TYPES = [
  { name: 'Failure', counts: true, definition: 'Error reached the customer.' },
  { name: 'Mistake', counts: true, definition: 'Execution error by the team.' },
  { name: 'Near Miss', counts: false, definition: 'Error caught before it reached the customer.' },
  { name: 'Performance', counts: false, definition: 'Process, follow-up or communication gap.' },
];
// Recordable Incident (Safety Incident / Near Miss Report PWH-FRM-204-1, Section 2) is always an OTIF incident type,
// also after a workbook import replaces the list. It doesn't count in Order Accuracy % unless changed in Settings.
const RECORDABLE = { name: 'Recordable Incident', counts: false, definition: 'Injury/illness needing treatment beyond first aid, lost time, or restricted duty.' };
const withRecordable = list => (list.some(t => String(t.name).trim().toLowerCase() === 'recordable incident') ? list : [...list, RECORDABLE]);
export function withRailDefaults(d = {}) {
  return {
    openCarWindowDays: 30,
    turnCharge: 500, // $ per turned rail car (accessorial charge)
    customers: [],
    ...d,
  };
}

// ============================================================ Firebase backend
async function firebaseBackend() {
  const [{ initializeApp }, A, F] = await Promise.all([
    import(FB + 'firebase-app.js'), import(FB + 'firebase-auth.js'), import(FB + 'firebase-firestore.js'),
  ]);
  const app = initializeApp(firebaseConfig);
  const auth = A.getAuth(app);
  const db = F.initializeFirestore(app, {
    localCache: F.persistentLocalCache({ tabManager: F.persistentMultipleTabManager() }),
  });
  const snapDocs = s => s.docs.map(d => ({ id: d.id, ...d.data() }));

  return {
    onAuth(cb) {
      A.onAuthStateChanged(auth, u => cb(u ? { uid: u.uid, email: u.email, name: u.displayName || u.email } : null));
    },
    async ensureUserDoc(u) {
      const ref = F.doc(db, 'users', u.uid);
      const snap = await F.getDoc(ref);
      if (!snap.exists()) {
        await F.setDoc(ref, { email: u.email, name: u.name, role: 'pending', createdAt: F.serverTimestamp() });
        return 'pending';
      }
      return snap.data().role || 'pending';
    },
    signInProvider(kind) {
      const p = kind === 'microsoft' ? new A.OAuthProvider('microsoft.com') : new A.GoogleAuthProvider();
      return A.signInWithPopup(auth, p);
    },
    signInEmail: (e, p) => A.signInWithEmailAndPassword(auth, e, p),
    signUpEmail: (e, p) => A.createUserWithEmailAndPassword(auth, e, p),
    resetPassword: e => A.sendPasswordResetEmail(auth, e),
    signOut: () => A.signOut(auth),

    subscribe(coll, cb) {
      return new Promise((res, rej) => {
        let first = true;
        F.onSnapshot(F.collection(db, coll), s => { cb(snapDocs(s)); if (first) { first = false; res(); } },
          err => { console.error(coll, err); cb([]); if (first) { first = false; res(); } });
      });
    },
    watchDoc(coll, id, cb) {
      F.onSnapshot(F.doc(db, coll, id), s => cb(s.exists() ? s.data() : {}), err => { console.error(err); cb({}); });
    },
    async add(coll, data) {
      const r = await F.addDoc(F.collection(db, coll), { ...data, _created: F.serverTimestamp(), _by: store.user?.email || '' });
      return r.id;
    },
    async addWithRef(coll, prefix, data) {
      return F.runTransaction(db, async tx => {
        const cref = F.doc(db, 'counters', coll);
        const c = await tx.get(cref);
        let next = c.exists() ? c.data().next : maxRef(coll, prefix) + 1;
        const id = \`\${prefix}-\${String(next).padStart(4, '0')}\`;
        tx.set(cref, { next: next + 1 });
        tx.set(F.doc(db, coll, id), { ...data, _created: F.serverTimestamp(), _by: store.user?.email || '' });
        return id;
      });
    },
    set: (coll, id, data, merge = false) => F.setDoc(F.doc(db, coll, id), data, { merge }),
    async get(coll, id) { const s = await F.getDoc(F.doc(db, coll, id)); return s.exists() ? { id: s.id, ...s.data() } : null; },
    update: (coll, id, data) => F.updateDoc(F.doc(db, coll, id), { ...data, _updated: F.serverTimestamp(), _updBy: store.user?.email || '' }),
    remove: (coll, id) => F.deleteDoc(F.doc(db, coll, id)),
    async replaceAll(coll, docs, onProgress) {
      const existing = await F.getDocs(F.collection(db, coll));
      const ops = [...existing.docs.map(d => ['del', d.ref]), ...docs.map(d => ['set', d.id ? F.doc(db, coll, d.id) : F.doc(F.collection(db, coll)), d])];
      for (let i = 0; i < ops.length; i += 450) {
        const b = F.writeBatch(db);
        for (const [op, ref, data] of ops.slice(i, i + 450)) op === 'del' ? b.delete(ref) : b.set(ref, clean(data));
        await b.commit();
        onProgress?.(Math.min(i + 450, ops.length), ops.length);
      }
      const prefix = REF_PREFIX[coll];
      if (prefix) await F.setDoc(F.doc(db, 'counters', coll), { next: Math.max(0, ...docs.map(d => refNum(d.id, prefix))) + 1 });
    },
    async writeMany(coll, docs) {
      for (let i = 0; i < docs.length; i += 450) {
        const b = F.writeBatch(db);
        for (const d of docs.slice(i, i + 450)) {
          if (d._delete) b.delete(F.doc(db, coll, d._delete));
          else b.set(d.id ? F.doc(db, coll, d.id) : F.doc(F.collection(db, coll)), clean(d));
        }
        await b.commit();
      }
    },
    async listUsers() { return snapDocs(await F.getDocs(F.collection(db, 'users'))); },
  };
}

const refNum = (id, prefix) => (id && id.startsWith(prefix + '-') ? parseInt(id.slice(prefix.length + 1), 10) || 0 : 0);
const maxRef = (coll, prefix) => Math.max(0, ...store.rows(coll).map(d => refNum(d.id, prefix)));

// ============================================================ Demo backend (localStorage)
function demoBackend() {
  const KEY = 'atl-ops-demo-v1';
  let mem;
  try { mem = JSON.parse(localStorage.getItem(KEY)) || {}; } catch { mem = {}; }
  const subs = new Map(); // coll -> [cb]
  const docSubs = new Map();
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(mem)); } catch (e) { console.warn('Demo storage full', e); } };
  const coll = c => (mem[c] ||= {});
  const list = c => Object.entries(coll(c)).map(([id, d]) => ({ id, ...d }));
  const fire = c => {
    save();
    (subs.get(c) || []).forEach(cb => cb(list(c)));
    if (c === 'config') for (const [id, cbs] of docSubs) cbs.forEach(cb => cb(coll('config')[id] || {}));
  };
  const newId = () => Math.random().toString(36).slice(2, 12);

  return {
    onAuth(cb) { setTimeout(() => cb({ uid: 'demo', email: 'demo@local', name: 'Demo User' }), 0); },
    async ensureUserDoc() { return 'admin'; },
    signInProvider: async () => {}, signInEmail: async () => {}, signUpEmail: async () => {}, resetPassword: async () => {},
    signOut: async () => { if (confirm('Demo mode: clear all demo data stored in this browser?')) { localStorage.removeItem(KEY); location.reload(); } },
    async subscribe(c, cb) { (subs.get(c) || subs.set(c, []).get(c)).push(cb); cb(list(c)); },
    watchDoc(c, id, cb) { (docSubs.get(id) || docSubs.set(id, []).get(id)).push(cb); cb(coll(c)[id] || {}); },
    async add(c, data) { const id = newId(); coll(c)[id] = data; fire(c); return id; },
    async addWithRef(c, prefix, data) {
      const id = \`\${prefix}-\${String(maxRef(c, prefix) + 1).padStart(4, '0')}\`;
      coll(c)[id] = data; fire(c); return id;
    },
    async set(c, id, data, merge) { coll(c)[id] = merge ? { ...coll(c)[id], ...data } : data; fire(c); },
    async get(c, id) { return coll(c)[id] ? { id, ...coll(c)[id] } : null; },
    async update(c, id, data) { coll(c)[id] = { ...coll(c)[id], ...data }; fire(c); },
    async remove(c, id) { delete coll(c)[id]; fire(c); },
    async replaceAll(c, docs, onProgress) {
      mem[c] = {};
      for (const d of docs) coll(c)[d.id || newId()] = clean(d);
      onProgress?.(docs.length, docs.length); fire(c);
    },
    async writeMany(c, docs) {
      for (const d of docs) { if (d._delete) delete coll(c)[d._delete]; else coll(c)[d.id || newId()] = clean(d); }
      fire(c);
    },
    async listUsers() { return [{ id: 'demo', email: 'demo@local', name: 'Demo User', role: 'admin' }]; },
  };
}`]);

