//
// A throughput row keeps the customer's main unit in Inbound / Outbound (with \`unit\` naming it) — pallets in
// 6049, tons in 6021 — so totals, charts and the damage rate per 10,000 work as before. Any other units the
// customer reports go in their own fields: mtIn / mtOut, palletsIn / palletsOut, bundlesIn / bundlesOut.
import { norm } from '@atl/util.js';

export const UNIT_SETS = {
  'Pallets': ['Pallets'],
  'Tons + MT': ['Tons', 'MT'],
  'Pallets + Tons + Bundles': ['Pallets', 'Tons', 'Bundles'],
};
const FIELD = { Pallets: 'pallets', Tons: 'tons', MT: 'mt', Bundles: 'bundles' };

/** Units a customer reports, in entry order. Blank = the building's unit (6049 pallets, 6021 tons). */
export const unitsOf = c => UNIT_SETS[c.units] || [String(c.building) === '6049' ? 'Pallets' : 'Tons'];

/**
 * The unit kept in Inbound / Outbound — always the building's unit (6049 pallets, 6021 tons), so building
 * totals never mix units. A customer that doesn't report that unit (e.g. Nexus pallets into 6021) leaves
 * Inbound / Outbound at 0 and its numbers go in the other-unit fields.
 */
export const mainUnit = c => (String(c.building) === '6049' ? 'Pallets' : 'Tons');

/** The customer's name plus its "also known as" names (files and old entries may use any of them). */
export const namesOf = c => [c.name, ...String(c.aliases || '').split(',')].map(s => s.trim()).filter(Boolean);
