ATL_SRC.push(['@atl/views/empids.js', 0, `// Data ▸ Employees ▸ "Sync with HR file": reads the HR system's Employee Information export (.csv) and makes the
// roster match it — HR Employee Ids, the spelling of each name (roster name and labor name, with every log entry under
// the old name moved to the new one), duplicate roster / labor records merged, and people missing from the roster
// added. Everything is shown first; nothing is saved until Save.
import { store } from '@atl/store.js';
import { esc, norm, toast } from '@atl/util.js';
import { nameScore } from '@atl/hrpdf.js';

/** Minimal CSV parser (quoted fields, commas and quotes inside quotes). */
function parseCSV(text) {
  const rows = []; let row = [], cell = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') q = false; else cell += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\\n' || c === '\\r') { if (c === '\\r' && text[i + 1] === '\\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if (cell || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

/** HR spelling, tidied: single spaces, no spaces around hyphens ("Aguilera- Avila" → "Aguilera-Avila"). */
const tidy = s => String(s || '').replace(/\\s*-\\s*/g, '-').replace(/\\s+/g, ' ').trim();

/** [{ id, first, last, status, full }] from the export — the table starts at the "Employee Id" header row. */
function readExport(text) {
  const rows = parseCSV(text), h = rows.findIndex(r => r.some(c => norm(c) === 'EMPLOYEE ID'));
  if (h < 0) throw new Error('This file has no "Employee Id" column — use the HR system\\'s Employee Information export.');
  const col = name => rows[h].findIndex(c => norm(c) === name);
  const [ci, cf, cl, cs] = ['EMPLOYEE ID', 'FIRST NAME', 'LAST NAME', 'EMPLOYEE STATUS'].map(col);
  if (cf < 0 || cl < 0) throw new Error('The export needs "First Name" and "Last Name" columns.');
  return rows.slice(h + 1).filter(r => (r[ci] || '').trim()).map(r => {
    const first = tidy(r[cf]), last = tidy(r[cl]);
    return { id: r[ci].trim(), first, last, full: \`\${first} \${last}\`.trim(), status: cs >= 0 ? (r[cs] || '').trim() : '' };
  });
}

// Log fields that hold an employee's name. Roster names (UPPER CASE) and labor names (Title Case) are kept separately.
const ROSTER_REFS = [['attendance', 'employee'], ['discipline', 'employee'], ['recognition', 'recipient'], ['damage', 'operator'], ['otif', 'responsible']];
const LABOR_REFS = [['labor', 'employee'], ['opmoves', 'operator']];
const NEEDS = ['employees', ...new Set([...ROSTER_REFS, ...LABOR_REFS].map(([c]) => c))];
/** OTIF "Responsible Party" can name several people ("JOHN DOE / JANE DOE"): replace whole-name matches inside it. */
const swapIn = (v, from, to) => String(v).replace(new RegExp(\`(^|[^A-Za-z])\${from.replace(/[.*+?^\${}()|[\\]\\\\]/g, '\\\\$&')}(?=$|[^A-Za-z])\`, 'gi'), (m, pre) => pre + to);
const refsTo = (refs, name) => refs.flatMap(([coll, key]) => store.rows(coll).filter(r => r[key] && (key === 'responsible' ? swapIn(r[key], name, '\\u0000') !== String(r[key]) : norm(r[key]) === norm(name))).map(r => [coll, key, r]));

/** Work out every change the HR file implies. */
function plan(people) {
  const emps = store.rows('employees'), used = new Set();
  const out = { renames: [], merges: [], ids: [], adds: [], ambiguous: [], notInFile: [] };
  for (const p of people) {
    const scored = emps.filter(e => !used.has(e.id)).map(e => [e, Math.max(nameScore(p.full, e.name || ''), nameScore(p.full, e.laborName || ''))]).filter(([, s]) => s > 0).sort((a, b) => b[1] - a[1]);
    const top = scored.filter(([, s]) => s === scored[0]?.[1]).map(([e]) => e);
    let e = null, merge = null;
    if (top.length === 1) e = top[0];
    else if (top.length === 2) {
      // A roster-only record and a labor-only record for the same person (their link was misspelled): merge them.
      const ros = top.find(x => x.name && !x.laborName), lab = top.find(x => !x.name && x.laborName);
      if (ros && lab) { e = ros; merge = lab; }
    }
    if (!e) { (scored.length ? out.ambiguous : out.adds).push({ p, options: top }); continue; }
    used.add(e.id); if (merge) used.add(merge.id);
    const rosterName = p.full.toUpperCase(), laborName = p.full;
    const curLabor = merge ? merge.laborName : e.laborName;
    if (merge) out.merges.push({ p, e, lab: merge });
    if (e.name && e.name !== rosterName) out.renames.push({ p, e, kind: 'roster', from: e.name, to: rosterName, refs: refsTo(ROSTER_REFS, e.name) });
    if (curLabor && curLabor !== laborName) out.renames.push({ p, e, kind: 'labor', from: curLabor, to: laborName, refs: refsTo(LABOR_REFS, curLabor) });
    const curId = String(e.hrId || merge?.hrId || '').trim();
    if (curId !== p.id) out.ids.push({ p, e, from: curId });
  }
  // Active on the roster but not in the HR file (the export leaves out terminated employees) — listed, not changed.
  out.notInFile = emps.filter(e => e.name && norm(e.rosterStatus) === 'ACTIVE' && !used.has(e.id));
  return out;
}

async function apply(pl, addMissing) {
  let n = 0;
  for (const m of pl.merges) {
    // Copy the labor-only record's details onto the roster record, then remove the duplicate.
    const lab = m.lab, keep = {};
    for (const k of ['laborName', 'payType', 'defaultBuilding', 'laborActive', 'hrId', 'manager', 'shiftStart']) if (lab[k] && !m.e[k]) keep[k] = lab[k];
    keep.notes = [m.e.notes, lab.notes && !/^Roster link not found/i.test(lab.notes) ? lab.notes : ''].filter(Boolean).join(' · ');
    await store.update('employees', m.e.id, keep); await store.remove('employees', lab.id); n++;
  }
  for (const r of pl.renames) {
    for (const [coll, key, row] of r.refs) await store.update(coll, row.id, { [key]: key === 'responsible' ? swapIn(row[key], r.from, r.to) : r.to });
    await store.update('employees', r.e.id, r.kind === 'roster' ? { name: r.to } : { laborName: r.to }); n++;
  }
  for (const x of pl.ids) { await store.update('employees', x.e.id, { hrId: x.p.id }); n++; }
  if (addMissing) for (const a of pl.adds) {
    await store.add('employees', { name: a.p.full.toUpperCase(), rosterStatus: 'Active', laborName: a.p.full, laborActive: 'Y', payType: 'Hourly', laborCategory: 'Operator', hrId: a.p.id, shiftStart: '07:50', notes: 'Added from the HR Employee Information export — set Home Facility.' }); n++;
  }
  return n;
}

/** Open the file picker, show what the HR file will change, and apply it on Save. */
export function importEmployeeIds(rerender) {
  const pick = document.createElement('input');
  pick.type = 'file'; pick.accept = '.csv,text/csv';
  pick.addEventListener('change', async () => {
    const file = pick.files[0]; if (!file) return;
    let pl;
    try { await store.need(NEEDS); pl = plan(readExport(await file.text())); } catch (err) { toast(err.message, 'bad'); return; }
    const sec = (title, items, fmt, note = '') => items.length ? \`<h4>\${title} <span class="muted">(\${items.length})</span></h4>\${note ? \`<p class="muted small">\${note}</p>\` : ''}<ul class="ids-list">\${items.map(fmt).join('')}</ul>\` : '';
    const refsTxt = refs => { const by = {}; for (const [c] of refs) by[c] = (by[c] || 0) + 1; return Object.entries(by).map(([c, k]) => \`\${k} \${c}\`).join(', '); };
    const el = document.createElement('div');
    el.className = 'modal-back ids-back';
    el.innerHTML = \`<div class="modal ids-pop" role="dialog" aria-modal="true" aria-labelledby="ids-title">
      <div class="modal-head"><h2 id="ids-title">Sync employees with \${esc(file.name)}</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
      <p class="muted small">The HR file is the reference: names are spelled as HR has them. Matched to the roster by name. Nothing is saved until you press Save.</p>
      \${sec('Name corrections', pl.renames, r => \`<li><b>\${esc(r.from)}</b> → <b>\${esc(r.to)}</b> <span class="muted">(\${r.kind} name\${r.refs.length ? \`; \${refsTxt(r.refs)} entr\${r.refs.length === 1 ? 'y' : 'ies'} moved to the new name\` : ''})</span></li>\`, 'Every log entry under the old name is moved to the new one, so the person\\'s history stays together.')}
      \${sec('Duplicate records merged', pl.merges, m => \`<li><b>\${esc(m.e.name)}</b> + labor record “\${esc(m.lab.laborName)}” → one record</li>\`, 'Roster and labor records for the same person that were not linked (misspelled link).')}
      \${sec('HR Employee Ids', pl.ids, x => \`<li><b>\${esc(x.p.full)}</b>: \${x.from ? \`\${esc(x.from)} → \` : ''}\${esc(x.p.id)}</li>\`)}
      \${pl.adds.length ? \`<h4>In the HR file but not on the roster <span class="muted">(\${pl.adds.length})</span></h4><label class="ids-add"><input type="checkbox" data-add checked> Add \${pl.adds.length === 1 ? 'them' : 'them'} to the roster as Active (set their Home Facility afterwards)</label><ul class="ids-list">\${pl.adds.map(a => \`<li>\${esc(a.p.full)} · \${esc(a.p.id)}</li>\`).join('')}</ul>\` : ''}
      \${sec('Could not tell which employee — not changed', pl.ambiguous, a => \`<li>\${esc(a.p.full)} · \${esc(a.p.id)} <span class="muted">(\${a.options.map(o => esc(o.name || o.laborName)).join(' / ')})</span></li>\`)}
      \${sec('Active on the roster but not in the HR file — not changed', pl.notInFile, e => \`<li>\${esc(e.name)}</li>\`, 'The HR export leaves out terminated employees. If any of these have left, set them to “Not on Current Roster”.')}
      \${pl.renames.length + pl.merges.length + pl.ids.length + pl.adds.length ? '' : '<p><b>Everything already matches the HR file.</b></p>'}
      <div class="modal-foot"><span></span><div><button type="button" class="btn ghost" data-close>Cancel</button>
        <button type="button" class="btn primary" data-save \${pl.renames.length + pl.merges.length + pl.ids.length + pl.adds.length ? '' : 'disabled'}>Save changes</button></div></div></div>\`;
    document.body.appendChild(el);
    const close = () => el.remove();
    el.addEventListener('click', e => { if (e.target === el || e.target.closest('[data-close]')) close(); });
    el.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
    el.querySelector('[data-save]').addEventListener('click', async e => {
      e.target.disabled = true; e.target.textContent = 'Saving…';
      try { const n = await apply(pl, !!el.querySelector('[data-add]')?.checked); close(); rerender?.(); toast(\`Employees synced with the HR file — \${n} change\${n === 1 ? '' : 's'} saved\`); }
      catch (err) { console.error(err); toast(\`Stopped part-way: \${err.message}\`, 'bad'); close(); rerender?.(); }
    });
    el.querySelector('[data-save]').focus();
  });
  pick.click();
}`]);

