ATL_SRC.push(['@atl/views/importer.js', 0, `// One-time (or repeatable) import of the "Atlanta Division - Rail OTIF KPI Dashboard.xlsx" workbook.
// Runs entirely in the browser: the file is parsed with SheetJS and written to the database.
import { store, withDefaults, withRailDefaults } from '@atl/store.js';
import { esc, excelDate, excelTime, norm, toast, $ } from '@atl/util.js';
import { page, section, table } from '@atl/ui.js';
import { isCustomer } from '@atl/throughput.js';

const SHEETJS = 'https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs';
let parsed = null, busy = false, progress = '';

const s = v => (v == null ? '' : String(v).trim());
const n = v => (v === '' || v == null || isNaN(+v) ? '' : +v);
const pad = i => String(i).padStart(4, '0');

export async function parseWorkbook(buf) {
  const XLSX = await import(SHEETJS);
  const wb = XLSX.read(buf, { type: 'array' });
  const sheet = name => wb.Sheets[name];
  const rows = (name, start) => {
    const ws = sheet(name); if (!ws) return [];
    return XLSX.utils.sheet_to_json(ws, { header: 'A', raw: true, defval: '' }).map(r => ({ ...r, _row: r.__rowNum__ + 1 })).filter(r => r._row >= start);
  };
  const cell = (name, ref) => sheet(name)?.[ref]?.v ?? '';
  const refId = (r, prefix) => (s(r.B).startsWith(prefix + '-') ? s(r.B) : \`\${prefix}-\${pad(r._row - 6)}\`);
  const out = {};

  out.otif = rows('OTIF Log', 7).filter(r => s(r.C)).map(r => ({
    id: refId(r, 'OTIF'), date: excelDate(r.C), facility: s(r.E), customer: s(r.F), type: s(r.G), category: s(r.H), responsible: s(r.I),
    description: s(r.J), rootCause: s(r.L), corrective: s(r.M), capa: s(r.N), status: s(r.O), cost: n(r.P),
  }));
  out.attendance = rows('Attendance Log', 7).filter(r => s(r.D)).map(r => ({
    id: refId(r, 'ATT'), employee: s(r.C), date: excelDate(r.D), schedStart: excelTime(r.F), arrival: excelTime(r.G), leftEarly: excelTime(r.H),
    excused: s(r.K), reason: s(r.L), recordedBy: s(r.M), cleanupNote: s(r.P),
  }));
  out.damage = rows('Damage Log', 7).filter(r => s(r.C)).map(r => ({
    id: refId(r, 'DMG'), date: excelDate(r.C), facility: s(r.E), customer: s(r.F), stage: s(r.G), damageType: s(r.H), cause: s(r.I),
    responsible: s(r.J), product: s(r.K), qty: n(r.L), unit: s(r.M), value: n(r.N), operator: s(r.O), recordedBy: s(r.P),
    photos: s(r.Q), claimNo: s(r.R), claimStatus: s(r.S), notes: s(r.T),
  }));
  out.labor = rows('Labor', 7).filter(r => s(r.B) && s(r.E)).map(r => ({
    weekEnding: excelDate(r.B), building: s(r.D), employee: s(r.E), payType: s(r.F), reg: n(r.G), ot: n(r.H),
  }));
  out.throughput = rows('Customer Throughput', 7).filter(r => s(r.B) && s(r.E)).map(r => ({
    weekEnding: excelDate(r.B), building: s(r.D), customer: s(r.E), unit: s(r.F), inbound: n(r.G), outbound: n(r.H),
  }));
  out.recognition = rows('Recognition', 7).filter(r => s(r.B) && s(r.D)).map(r => ({
    month: excelDate(r.B).slice(0, 8) + '01', award: s(r.C), recipient: s(r.D), notes: s(r.E),
  }));
  out.discipline = rows('Disciplinary Log', 7).filter(r => s(r.C) && s(r.D)).map(r => ({
    id: refId(r, 'DSC'), date: excelDate(r.C), employee: s(r.D), category: s(r.F), action: s(r.G), description: s(r.H),
    issuedBy: s(r.I), signed: s(r.J), notes: s(r.N),
  }));

  // Employees: roster (B–F) merged with labor-name setup (G–N) via "Attendance Roster Name" (H).
  const emp = new Map();
  for (const r of rows('Employees', 6)) if (s(r.B)) emp.set(norm(r.B), { name: s(r.B).toUpperCase(), rosterStatus: s(r.C), homeFacility: s(r.D), notes: s(r.E), shiftStart: excelTime(r.F) });
  for (const r of rows('Employees', 6)) {
    if (!s(r.G)) continue;
    const labor = { laborName: s(r.G), payType: !s(r.I) || norm(s(r.I)) === 'EMPLOYEE' ? 'Hourly' : s(r.I), defaultBuilding: s(r.J), laborActive: s(r.K) || 'Y', hrId: s(r.N) };
    const key = norm(r.H);
    if (key && emp.has(key) && !emp.get(key).laborName) Object.assign(emp.get(key), labor);
    else emp.set('labor:' + norm(r.G), { name: '', rosterStatus: '', homeFacility: s(r.J), notes: s(r.H) ? \`Roster link not found: \${s(r.H)}\` : '', ...labor });
  }
  out.employees = [...emp.values()];

  out.monthly = rows('Monthly Inputs', 7).filter(r => typeof r.B === 'number').map(r => {
    const iso = excelDate(r.B);
    return { id: iso.slice(0, 7), month: iso.slice(0, 8) + '01', loads6049: n(r.C), hc6049: n(r.D), loads6021: n(r.E), hc6021: n(r.F), notes: s(r.J) };
  }).map(m => Object.fromEntries(Object.entries(m).filter(([, v]) => v !== '')));

  // Settings
  const S = 'Settings', col = (letter, from = 6, to = 120) => {
    const vals = [];
    for (let i = from; i <= to; i++) { const v = s(cell(S, letter + i)); if (v) vals.push(v); else if (vals.length && !s(cell(S, letter + (i + 1)))) break; }
    return vals;
  };
  const incidentTypes = [];
  for (let i = 14; i < 19; i++) { const nm = s(cell(S, 'B' + i)); if (nm) incidentTypes.push({ name: nm, counts: /^y/i.test(s(cell(S, 'C' + i))), definition: s(cell(S, 'D' + i)) }); }
  const throughputCustomers = [];
  for (let i = 8; i < 47; i++) { const nm = s(cell(S, 'AD' + i)); if (nm) throughputCustomers.push({ name: nm, building: s(cell(S, 'AE' + i)), active: s(cell(S, 'AG' + i)) || 'Y' }); }
  const hrCounters = [];
  for (let i = 6; i <= 20; i++) { const c = s(cell(S, 'AK' + i)); if (c) hrCounters.push({ counter: c, countsAs: s(cell(S, 'AL' + i)) || 'Ignore' }); }
  const shift = cell(S, 'C7');
  out.settings = {
    reportingYear: n(cell(S, 'C6')) || new Date().getFullYear(),
    defaultShiftStart: typeof shift === 'number' ? excelTime(shift) : '07:50',
    orderAccuracyTarget: n(cell(S, 'C8')) || 0.99, attendanceTarget: n(cell(S, 'C9')) || 0.95,
    disciplineMonths: n(cell(S, 'C10')) || 12, salariedHours: n(cell(S, 'C38')) || 40,
    damageTarget6049: n(cell(S, 'C25')) === '' ? null : n(cell(S, 'C25')), damageTarget6021: n(cell(S, 'C26')) === '' ? null : n(cell(S, 'C26')),
    incidentTypes, throughputCustomers, hrCounters,
    lists: {
      incidentCategories: col('F'), customers: col('G'), facilities: col('H'), supervisors: col('I'), incidentStatus: col('J'),
      awardTypes: col('L'), rosterStatus: col('M'), damageStage: col('N'), damageType: col('O'), damageCause: col('P'),
      damageResponsible: col('Q'), damageUnit: col('R'), claimStatus: col('S'), disciplineCategories: col('U'), disciplineActions: col('V'),
    },
  };
  for (const [k, v] of Object.entries(out.settings.lists)) if (!v.length) delete out.settings.lists[k];

  // Rail
  const R = 'Rail Settings', railCustomers = [];
  for (let i = 6; i < 30; i++) {
    const nm = s(cell(R, 'B' + i)); if (!nm) break;
    railCustomers.push({ name: nm, tab: s(cell(R, 'C' + i)) || nm, freeDays: n(cell(R, 'D' + i)) || 5, rate: n(cell(R, 'E' + i)) || 40, building: s(cell(R, 'F' + i)) });
  }
  out.rail = { openCarWindowDays: n(cell(R, 'H11')) || 30, customers: railCustomers.map(({ tab, ...c }) => c) };
  // Column R ("Data Check") is a formula; anything else typed over it is a note worth keeping.
  const CHECKS = /^(Rail car # missing|CP date missing|CP date out of range|Release date not a date|Release before CP date|No release date)/;
  const railNotes = r => [s(r.K), s(r.R) && !CHECKS.test(s(r.R)) ? s(r.R) : ''].filter(Boolean).join(' · ');
  out.railcars = railCustomers.flatMap(c => rows(c.tab, 17).filter(r => ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'].some(k => s(r[k]))).map(r => ({
    customer: c.name, car: s(r.B).toUpperCase(), cpDate: excelDate(r.C), cpTime: excelTime(r.D), orderedDate: excelDate(r.E), orderedTime: excelTime(r.F),
    placedDate: excelDate(r.G), placedTime: excelTime(r.H), releasedDate: excelDate(r.I), releasedTime: excelTime(r.J), notes: railNotes(r), waive: s(r.L).toUpperCase(),
  })));
  return out;
}

const COLLS = ['employees', 'otif', 'attendance', 'damage', 'labor', 'throughput', 'recognition', 'discipline', 'monthly', 'railcars'];

const LOAD_FIELDS = ['loadsOut', 'loadsOutPrev', 'loadsIn', 'loadsInPrev'];

/**
 * The workbook has no load counts, so loads posted on Weekly Entry (Billing Activity files) are kept through a
 * "Replace everything": each workbook week takes the loads already in the app for the same week, building and
 * customer ("also known as" names count), and weeks posted in the app that aren't in the workbook stay as they are.
 * Monthly Inputs then add the loads up again from the throughput. Returns how many weeks' loads were kept.
 */
async function keepLoads(rows, customers) {
  await store.need(['throughput']);
  const who = name => customers.find(c => isCustomer(c, name))?.name || norm(name);
  const key = r => \`\${r.weekEnding}|\${String(r.building)}|\${norm(who(r.customer))}\`;
  const posted = new Map(store.rows('throughput').filter(r => LOAD_FIELDS.some(f => typeof r[f] === 'number')).map(r => [key(r), r]));
  let kept = 0;
  for (const r of rows) {
    const p = posted.get(key(r)); if (!p) continue;
    for (const f of LOAD_FIELDS) if (typeof p[f] === 'number') r[f] = p[f];
    posted.delete(key(r)); kept++;
  }
  // Left over: a week the workbook doesn't have keeps its whole row. In a week the workbook has (customer spelled
  // differently), only the loads are kept, on a row with no throughput, so the week's totals can't double.
  const weeks = new Set(rows.map(r => \`\${r.weekEnding}|\${String(r.building)}\`));
  for (const p of posted.values()) {
    const { id, ...doc } = p;
    if (!weeks.has(\`\${p.weekEnding}|\${String(p.building)}\`)) rows.push(doc);
    else rows.push({ weekEnding: p.weekEnding, building: String(p.building), customer: p.customer, unit: p.unit, inbound: 0, outbound: 0,
      ...Object.fromEntries(LOAD_FIELDS.filter(f => typeof p[f] === 'number').map(f => [f, p[f]])) });
    kept++;
  }
  return kept;
}

export async function writeImport(data, onStep = () => {}) {
  // Before the settings are replaced: the app's customer list has the "also known as" names.
  const customers = [...(store.settings?.throughputCustomers || []), ...data.settings.throughputCustomers];
  const kept = await keepLoads(data.throughput, customers);
  if (kept) onStep(\`Kept Weekly Entry loads for \${kept} customer-weeks\`);
  await store.saveConfig('settings', withDefaults(data.settings));
  await store.saveConfig('rail', withRailDefaults(data.rail));
  for (const c of COLLS) {
    onStep(\`Writing \${c} (\${data[c].length})…\`);
    await store.replaceAll(c, data[c], (i, t) => onStep(\`Writing \${c}: \${i}/\${t}\`));
  }
  onStep('Done');
}

// Test hook: window.atlImport(arrayBuffer)
window.atlImport = async buf => { const d = await parseWorkbook(buf); await writeImport(d); return Object.fromEntries(COLLS.map(c => [c, d[c].length])); };

export default {
  needs: () => [],
  render() {
    if (!store.can('admin')) return page('Import from Excel', 'Admin access is needed.');
    const preview = parsed ? section('Ready to import', table([{ label: 'Collection', key: 'c' }, { label: 'Rows', key: 'n', type: 'number' }],
      [...COLLS.map(c => ({ c, n: parsed[c].length })), { c: 'settings · incident types', n: parsed.settings.incidentTypes.length }, { c: 'settings · throughput customers', n: parsed.settings.throughputCustomers.length }, { c: 'rail · customers', n: parsed.rail.customers.length }]) +
      \`<p class="warnline">⚠ Importing <b>replaces</b> all current data in every collection listed above, and the settings.</p>
       <p class="muted">Loads posted on Weekly Entry (from the Billing Activity files) are kept: the workbook has no load counts, so each week keeps the loads already in the app, and Monthly Inputs add them up again.</p>
       <button class="btn primary" data-go \${busy ? 'disabled' : ''}>\${busy ? 'Importing…' : 'Replace everything with this workbook'}</button> <span class="muted">\${esc(progress)}</span>\`) : '';
    return page('Import from Excel', 'Load the Rail OTIF KPI Dashboard workbook (.xlsx). The file is read in your browser — nothing is uploaded anywhere except the rows written to the database.') +
      section('1 · Choose the workbook', \`<input type="file" accept=".xlsx,.xlsm" data-file> <span class="muted">\${esc(progress && !parsed ? progress : '')}</span>\`) + preview;
  },
  after(root, p, rerender) {
    $('[data-file]', root)?.addEventListener('change', async e => {
      const f = e.target.files[0]; if (!f) return;
      progress = 'Reading workbook…'; parsed = null; rerender();
      try { parsed = await parseWorkbook(await f.arrayBuffer()); progress = ''; } catch (err) { console.error(err); progress = 'Could not read the file: ' + err.message; }
      rerender();
    });
    $('[data-go]', root)?.addEventListener('click', async () => {
      if (!confirm('Replace ALL current data with the contents of this workbook?')) return;
      busy = true; rerender();
      try { await writeImport(parsed, m => { progress = m; const el = $('[data-go] + .muted'); if (el) el.textContent = m; }); toast('Import complete'); parsed = null; location.hash = '#/'; }
      catch (err) { console.error(err); toast(err.message, 'bad'); progress = 'Failed: ' + err.message; }
      busy = false; rerender();
    });
  },
};`]);

