ATL_SRC.push(['@atl/views/quality.js', 0, `// Data Quality Check: live checks across every log, in the same look as the KPI dashboards.
import { store } from '@atl/store.js';
import { dataQuality } from '@atl/calc.js';
import { esc, fmtNum, fmtPct } from '@atl/util.js';
import { section, kpi, chart, chartBox } from '@atl/ui.js';

const ROUTE = { otif: '#/log/otif', attendance: '#/log/attendance', damage: '#/log/damage', labor: '#/log/labor', throughput: '#/log/throughput', discipline: '#/log/discipline', railcars: '#/rail', monthly: '#/monthly' };
const C = { fix: '#c0392b', review: '#d4a017', ok: '#1a9e7a' };
let view = 'all'; // all | open | fix | review — status filter for the table (kept while you move around)

const goLink = c => {
  if (!c.ids.length) return '';
  if (c.coll && ROUTE[c.coll]?.startsWith('#/log/')) return \`<a class="dq-go" href="\${ROUTE[c.coll]}?ids=\${encodeURIComponent(c.ids.join(','))}">Show \${c.ids.length} ›</a>\`;
  return c.coll ? \`<a class="dq-go" href="\${ROUTE[c.coll]}">Open ›</a>\` : '';
};

export default {
  needs: () => ['otif', 'attendance', 'damage', 'labor', 'throughput', 'railcars', 'monthly', 'employees', ...(store.can('confidential') ? ['discipline'] : [])],
  render(p) {
    // ?area=OTIF (from the Data Quality drop-down or the chart) narrows the page to one area.
    const area = p?.query?.area || '', all = dataQuality();
    const checks = area ? all.filter(c => c.area === area) : all;
    const issues = sev => checks.filter(c => c.severity === sev).reduce((a, c) => a + c.ids.length, 0);
    const fix = issues('FIX'), review = issues('REVIEW');
    const passing = checks.filter(c => !c.ids.length).length;
    const areas = [...new Set(all.map(c => c.area))];
    const fixAreas = [...new Set(checks.filter(c => c.severity === 'FIX' && c.ids.length).map(c => c.area))];

    const tiles = [
      kpi('Open FIX items', fmtNum(fix), fix ? 'Fix these first — they change the KPIs' : 'Nothing that affects the KPIs', fix ? 'bad' : 'good'),
      kpi('Open REVIEW items', fmtNum(review), review ? 'Worth a look; KPIs not affected' : 'Nothing to review', review ? 'warn' : 'good'),
      kpi('Checks passing', \`\${fmtNum(passing)} <small>/ \${fmtNum(checks.length)}</small>\`, checks.length ? \`\${fmtPct(passing / checks.length, 0)} of checks have no issues\` : '', passing === checks.length ? 'good' : ''),
      kpi('Areas with FIX items', fmtNum(fixAreas.length), fixAreas.length ? esc(fixAreas.join(', ')) : 'All areas clear', fixAreas.length ? 'bad' : 'good'),
    ];

    const counts = { all: checks.length, open: checks.filter(c => c.ids.length).length, fix: checks.filter(c => c.severity === 'FIX' && c.ids.length).length, review: checks.filter(c => c.severity === 'REVIEW' && c.ids.length).length };
    const chips = [['all', 'All checks'], ['open', 'Open only'], ['fix', 'FIX open'], ['review', 'REVIEW open']]
      .map(([k, l]) => \`<button type="button" class="dq-chip\${view === k ? ' on' : ''}" data-dq-view="\${k}" aria-pressed="\${view === k}">\${l} <b>\${counts[k]}</b></button>\`).join('');
    const areaSel = \`<label class="xl-chg">Area <select data-dq-area aria-label="Show checks for one area"><option value="">All areas</option>\${areas.map(a => \`<option \${a === area ? 'selected' : ''}>\${esc(a)}</option>\`).join('')}</select></label>\`;

    const rows = checks.map(c => {
      const open = c.ids.length > 0, sev = c.severity === 'FIX' ? 'fix' : 'review';
      const ex = c.ids.slice(0, 4).join(', ') + (c.ids.length > 4 ? ', …' : '');
      return \`<tr class="dq-row \${open ? 'open ' + sev : 'ok'}" data-open="\${open}" data-sev="\${sev}">
        <td class="num">\${all.indexOf(c) + 1}</td>
        <td><span class="dq-area">\${esc(c.area)}</span></td>
        <td class="dq-check">\${esc(c.check)}</td>
        <td class="num dq-n">\${open ? fmtNum(c.ids.length) : '0'}</td>
        <td><span class="dq-pill \${sev}">\${c.severity}</span></td>
        <td>\${open ? \`<span class="dq-status \${sev}">● Open</span>\` : '<span class="dq-status ok">✓ OK</span>'}</td>
        <td class="clip"><div class="clip-in mono small" title="\${esc(c.ids.join(', '))}">\${esc(ex)}</div></td>
        <td class="dq-what">\${esc(c.what)}</td>
        <td>\${goLink(c)}</td></tr>\`;
    }).join('') || \`<tr><td colspan="9" class="dq-empty">No \${esc(area)} checks.</td></tr>\`;

    return \`<div class="dash xl-dash dq-xl">
      <div class="xl-dash-head">
        <div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;Data Quality Check\${area ? \` — \${esc(area)}\` : ''}</h1>
          <p>Live checks across every log. Fix items marked FIX first — they change the KPIs. REVIEW items are worth a look.\${area ? \` Showing \${esc(area)} checks only · <a href="#/quality">Show all checks</a>.\` : ''}</p></div>
        <div class="xl-meta"><b>Checks run:</b><span class="xl-year">\${fmtNum(checks.length)}</span><b>Issues open</b><span class="xl-thru">\${fmtNum(fix + review)}</span>
          <span class="xl-meta-title">Data Quality</span>\${areaSel}</div>
        <div class="xl-tiles q" style="grid-template-columns:repeat(\${tiles.length}, minmax(0, 1fr))">\${tiles.join('')}</div>
        <div style="height:16px"></div>
      </div>\` +
      (area ? '' : section('Open Issues by Area', \`<div class="xl-chart"><h4>Open issues by area — FIX vs. REVIEW</h4>
        \${chartBox('ch-dq', Math.max(200, 50 + areas.length * 30), 'Open data-quality issues per area, split into FIX and REVIEW')}
        <p class="xl-foot">Click a bar to see only that area's checks.</p></div>\`)) +
      section('Checks', \`<div class="dq-tools" role="group" aria-label="Filter checks">\${chips}</div>
        <div class="xl-otif-wrap"><table class="xl-otif dq-table"><thead><tr><th>#</th><th>Area</th><th>Check</th><th>Issues</th><th>Severity</th><th>Status</th><th>Examples</th><th>What to do</th><th>Go</th></tr></thead>
        <tbody>\${rows}</tbody></table></div>
        <p class="xl-foot">Red rows have FIX issues, amber rows REVIEW issues; green ✓ means the check passes. Hover an Examples cell for every ID; "Show" opens the log filtered to those rows.</p>\`) +
      \`</div>\`;
  },

  after(root, p) {
    const area = p?.query?.area || '';
    // Status chips filter rows in place.
    const apply = () => {
      root.querySelectorAll('tr.dq-row').forEach(tr => {
        const open = tr.dataset.open === 'true', sev = tr.dataset.sev;
        tr.hidden = view === 'open' ? !open : view === 'fix' ? !(open && sev === 'fix') : view === 'review' ? !(open && sev === 'review') : false;
      });
      root.querySelectorAll('[data-dq-view]').forEach(b => { const on = b.dataset.dqView === view; b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); });
    };
    root.querySelectorAll('[data-dq-view]').forEach(b => b.addEventListener('click', () => { view = b.dataset.dqView; apply(); }));
    apply();
    root.querySelector('[data-dq-area]')?.addEventListener('change', e => { location.hash = e.target.value ? \`#/quality?area=\${encodeURIComponent(e.target.value)}\` : '#/quality'; });

    if (area) return;
    // Open issues by area: FIX (red) + REVIEW (amber) stacked; areas with nothing open show a green "0".
    const all = dataQuality(), areas = [...new Set(all.map(c => c.area))];
    const n = (a, sev) => all.filter(c => c.area === a && c.severity === sev).reduce((s, c) => s + c.ids.length, 0);
    const fixD = areas.map(a => n(a, 'FIX')), revD = areas.map(a => n(a, 'REVIEW'));
    const okLabels = { id: 'okLabels', afterDatasetsDraw(ch) {
      const ctx = ch.ctx, meta = ch.getDatasetMeta(1); ctx.save(); ctx.font = "600 11px 'Segoe UI', system-ui, sans-serif"; ctx.textBaseline = 'middle';
      meta.data.forEach((bar, i) => { const t = fixD[i] + revD[i]; ctx.fillStyle = t ? '#262626' : C.ok; ctx.fillText(t ? fmtNum(t) : '✓ 0', bar.x + 6, bar.y); });
      ctx.restore();
    } };
    chart('ch-dq', {
      type: 'bar',
      data: { labels: areas, datasets: [
        { label: 'FIX', data: fixD, backgroundColor: C.fix, stack: 'i', borderRadius: 2 },
        { label: 'REVIEW', data: revD, backgroundColor: C.review, stack: 'i', borderRadius: 2 },
      ] },
      options: { indexAxis: 'y', layout: { padding: { right: 40 } },
        plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, padding: 14 } }, tooltip: { mode: 'index', callbacks: { footer: it => \`Total open: \${fmtNum(it.reduce((s, t) => s + t.parsed.x, 0))} — click to open\` } } },
        scales: { x: { stacked: true, beginAtZero: true, title: { display: true, text: 'Open issues' }, ticks: { precision: 0 } }, y: { stacked: true, grid: { display: false } } },
        onClick: (e, els, ch) => { const i = els[0]?.index ?? ch.scales.y.getValueForPixel(e.y); if (areas[i]) location.hash = \`#/quality?area=\${encodeURIComponent(areas[i])}\`; },
        onHover: (e, els) => { e.native.target.style.cursor = els.length ? 'pointer' : 'default'; } },
      plugins: [okLabels],
    });
  },
};`]);

