ATL_SRC.push(['@atl/views/safety.js', 0, `// Safety Incidents & OSHA recordkeeping (#/safety): searchable incident history, the OSHA 300 Log and 300A Summary,
// TRIR / DART rates from the Labor log's hours, and OTIF Log Recordable Incidents missing a required report.
import { store } from '@atl/store.js';
import { esc, fmtNum, downloadXLSX, toast, $, $$, todayISO, isISO, yearOf } from '@atl/util.js';
import { kpi, chart, chartBox, table, badge } from '@atl/ui.js';
import { openIncidentForm, fromOtif, otifWaiting, classify, isRec, isDart, typesText, otherText, TYPES, CATEGORIES, STATUSES, OSHA_TYPES, FORM_NO } from '@atl/forms/incident.js';

const st = { q: '', year: '', facility: '', status: '', type: '', rec: false, tab: 'history', limit: 200 };
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const us = iso => (isISO(iso) ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(0, 4)}\` : '');
const cap = n => Math.min(180, Math.max(0, Math.round(+n || 0)));
const STATUS_TONE = { Open: 'bad', 'Under Investigation': 'warn', 'Actions Pending': 'warn', Closed: 'good' };
const TYPE_TONE = { 'Near Miss': 'warn', 'Unsafe Condition': 'info', 'Unsafe Act': 'info', 'Recordable Incident': 'bad' };
const TYPE_COL = { 'Near Miss': '#c0904d', 'Unsafe Condition': '#4d6f99', 'Unsafe Act': '#222b36', 'Recordable Incident': '#c0392b' };
const CLASS_SHORT = { Death: 'Death', 'Days away from work': 'Days away', 'Job transfer or restriction': 'Restricted', 'Other recordable case': 'Other recordable' };
const caseNo = r => r.oshaCaseNo || r.id;

const scoped = (year, fac) => store.rows('incidents').filter(r => (!year || String(yearOf(r.date)) === String(year)) && (!fac || String(r.facility) === fac));
/** Hours worked (regular + OT) and the average number of people working per week, from the Labor log. */
function hoursFor(year, fac) {
  const rows = store.rows('labor').filter(r => String(yearOf(r.weekEnding)) === String(year) && (!fac || String(r.building) === fac));
  let hours = 0; const weeks = new Map();
  for (const r of rows) { const h = (+r.reg || 0) + (+r.ot || 0); hours += h; if (h > 0) (weeks.get(r.weekEnding) || weeks.set(r.weekEnding, new Set()).get(r.weekEnding)).add(r.employee); }
  const avg = weeks.size ? [...weeks.values()].reduce((a, s) => a + s.size, 0) / weeks.size : 0;
  return { hours, avg: Math.round(avg), weeks: weeks.size };
}
const rate = (n, hours) => (hours ? (n * 200000) / hours : null);
/** OSHA 300 totals for a list of recordable cases. */
function totals(rec) {
  const c = k => rec.filter(r => classify(r) === k).length;
  return { G: c('Death'), H: c('Days away from work'), I: c('Job transfer or restriction'), J: c('Other recordable case'),
    K: rec.reduce((a, r) => a + cap(r.daysAway), 0), L: rec.reduce((a, r) => a + cap(r.daysRestricted), 0),
    M: OSHA_TYPES.map(t => rec.filter(r => (r.oshaType || 'Injury') === t).length) };
}
function filtered() {
  let rows = scoped(st.year, st.facility);
  if (st.status) rows = rows.filter(r => (r.status || 'Open') === st.status);
  if (st.type) rows = rows.filter(r => (r.types || []).includes(st.type));
  if (st.rec) rows = rows.filter(isRec);
  if (st.q) { const q = st.q.toLowerCase(); rows = rows.filter(r => JSON.stringify(r).toLowerCase().includes(q)); }
  return rows.sort((a, b) => String(b.date).localeCompare(String(a.date)) || String(b.time || '').localeCompare(String(a.time || '')) || String(b.id).localeCompare(String(a.id), undefined, { numeric: true }));
}
const frame = (title, id, h, aria) => \`<div class="xl-chart"><h4>\${title}</h4>\${chartBox(id, h, aria)}</div>\`;
const where = r => [r.facility, r.location || (r.area === 'Other' ? r.areaOther : r.area)].filter(Boolean).join(' – ');
const describe = r => [r.injuryNature, r.bodyPart, r.objectSubstance && \`struck / harmed by \${r.objectSubstance}\`].filter(Boolean).join('; ') || String(r.whatHappened || '').slice(0, 120);
const estName = () => (st.facility ? \`Piper Warehouse — Building \${st.facility}\` : 'Piper Warehouse — Atlanta Division (6021 & 6049)');

function historyTab(rows) {
  const cols = [
    { label: 'Report #', key: 'id', cls: 'mono' },
    { label: 'Date', key: 'date', type: 'date', cls: 't-date' },
    { label: 'Bldg', key: 'facility' },
    { label: 'Employee', key: 'employee' },
    { label: 'Type', html: true, get: r => (r.types || []).map(t => badge(t, TYPE_TONE[t])).join(' ') },
    { label: 'Category', get: r => otherText(r.categories, r.categoryOther), cls: 'clip' },
    { label: 'What happened', key: 'whatHappened', cls: 'clip t-textarea' },
    { label: 'Risk', get: r => String(r.risk || '').split(' — ')[0] },
    { label: 'OSHA', html: true, get: r => (isRec(r) ? badge(CLASS_SHORT[classify(r)], 'bad') : r.recordable === 'TBD' ? badge('To decide', 'warn') : r.recordable === 'No' ? '<span class="muted small">Not recordable</span>' : '') },
    { label: 'Status', html: true, get: r => badge(r.status || 'Open', STATUS_TONE[r.status || 'Open']) },
    { label: 'Files', get: r => r.files || '', type: 'number' },
    { label: 'OTIF', key: 'otifId', cls: 'mono' },
  ];
  const filters = st.q || st.status || st.type || st.rec;
  return \`<div class="toolbar">
      <input type="search" class="search" placeholder="Search reports — name, location, equipment, words…" value="\${esc(st.q)}" data-q aria-label="Search safety incident reports">
      <select data-status aria-label="Status"><option value="">All statuses</option>\${STATUSES.map(s => \`<option\${s === st.status ? ' selected' : ''}>\${s}</option>\`).join('')}</select>
      <select data-type aria-label="Incident type"><option value="">All types</option>\${TYPES.map(s => \`<option\${s === st.type ? ' selected' : ''}>\${s}</option>\`).join('')}</select>
      <label class="inline small"><input type="checkbox" data-rec \${st.rec ? 'checked' : ''}> OSHA recordable only</label>
      \${filters ? '<button type="button" class="btn ghost small" data-clear>Clear filters ✕</button>' : ''}
      <span class="count" aria-live="polite">\${rows.length} report\${rows.length === 1 ? '' : 's'}</span><span class="grow"></span>
      <button class="btn ghost" data-xlsx title="Download the reports shown as an Excel workbook">⬇ Export to Excel</button>
      \${store.can('edit') ? '<button class="btn primary" data-new>+ New report</button>' : ''}</div>
    <div class="log-scroll">\${table(cols, rows, { max: st.limit, rowAttr: r => \`data-id="\${esc(r.id)}" class="clickable" tabindex="0"\`, empty: filters ? 'No reports match these filters.' : \`No safety incident reports for \${esc(st.year)} yet.\` })}</div>
    \${rows.length > st.limit ? \`<div class="more"><button class="btn ghost" data-more>Show more</button></div>\` : ''}\`;
}

function log300Tab(rec) {
  const T = totals(rec), x = b => (b ? '✓' : '');
  return \`<div class="toolbar"><span class="muted small"><b>OSHA Form 300</b> — Log of Work-Related Injuries and Illnesses · \${esc(st.year)} · \${esc(estName())}\${st.facility ? '' : ' <span class="badge warn">OSHA needs one log per establishment — pick a building</span>'}</span>
      <span class="grow"></span><button class="btn ghost" data-x300>⬇ Export to Excel</button></div>
    <div class="table-wrap"><table class="grid sf-300"><thead>
      <tr class="grp"><th colspan="6">Identify the person &amp; describe the case</th><th colspan="4">Classify the case (most serious outcome)</th><th colspan="2">Number of days</th><th colspan="6">Injury or illness type</th></tr>
      <tr><th>(A) Case no.</th><th>(B) Employee name</th><th>(C) Job title</th><th>(D) Date of injury / onset</th><th>(E) Where the event occurred</th><th>(F) Injury / illness, body part, object / substance</th>
        <th>(G) Death</th><th>(H) Days away</th><th>(I) Transfer / restriction</th><th>(J) Other recordable</th><th>(K) Away from work</th><th>(L) Transfer / restriction</th>
        <th>(M1) Injury</th><th>(M2) Skin disorder</th><th>(M3) Respiratory</th><th>(M4) Poisoning</th><th>(M5) Hearing loss</th><th>(M6) All other illnesses</th></tr></thead>
      <tbody>\${rec.map(r => { const c = classify(r), t = r.oshaType || 'Injury'; return \`<tr data-id="\${esc(r.id)}" class="clickable" tabindex="0"><td class="mono">\${esc(caseNo(r))}</td><td>\${r.privacyCase === 'Y' ? '<i>Privacy Case</i>' : esc(r.employee)}</td><td>\${esc(r.jobTitle || '')}</td><td>\${esc(us(r.date))}</td><td>\${esc(where(r))}</td><td class="clip"><div class="clip-in" title="\${esc(describe(r))}">\${esc(describe(r))}</div></td>
        <td class="c">\${x(c === 'Death')}</td><td class="c">\${x(c === 'Days away from work')}</td><td class="c">\${x(c === 'Job transfer or restriction')}</td><td class="c">\${x(c === 'Other recordable case')}</td>
        <td class="num">\${cap(r.daysAway) || ''}</td><td class="num">\${cap(r.daysRestricted) || ''}</td>\${OSHA_TYPES.map(o => \`<td class="c">\${x(o === t)}</td>\`).join('')}</tr>\`; }).join('') || \`<tr><td colspan="18" class="empty">No OSHA recordable cases for \${esc(st.year)}\${st.facility ? ' in ' + esc(st.facility) : ''}.</td></tr>\`}</tbody>
      <tfoot><tr><td colspan="6"><b>Page totals</b></td><td class="c">\${T.G}</td><td class="c">\${T.H}</td><td class="c">\${T.I}</td><td class="c">\${T.J}</td><td class="num">\${T.K}</td><td class="num">\${T.L}</td>\${T.M.map(n => \`<td class="c">\${n}</td>\`).join('')}</tr></tfoot></table></div>
    <p class="xl-foot">Only cases marked “Recordable on the OSHA 300 Log = Yes” are listed. Classification is the most serious outcome (death › days away › job transfer / restriction › other). Days are capped at 180. Privacy cases show “Privacy Case” instead of the name — keep a separate confidential list of names. Click a row to open its report.</p>\`;
}

function summary300ATab(rec, h) {
  const T = totals(rec), trir = rate(rec.length, h.hours), dart = rate(rec.filter(isDart).length, h.hours);
  const box = (title, items) => \`<div class="sf-a-card"><h4>\${title}</h4>\${items.map(([k, v, code]) => \`<div class="sf-a-row"><span>\${code ? \`<b>(\${code})</b> \` : ''}\${k}</span><b>\${v}</b></div>\`).join('')}</div>\`;
  return \`<div class="toolbar"><span class="muted small"><b>OSHA Form 300A</b> — Summary of Work-Related Injuries and Illnesses · \${esc(st.year)} · \${esc(estName())}\${st.facility ? '' : ' <span class="badge warn">Post one 300A per establishment — pick a building</span>'}</span>
      <span class="grow"></span><button class="btn ghost" data-x300a>⬇ Export to Excel</button><button class="btn primary" data-print300a>🖨 Print 300A for posting</button></div>
    <div class="sf-a-grid">
      \${box('Number of cases', [['Total deaths', T.G, 'G'], ['Cases with days away from work', T.H, 'H'], ['Cases with job transfer or restriction', T.I, 'I'], ['Other recordable cases', T.J, 'J']])}
      \${box('Number of days', [['Days away from work', fmtNum(T.K), 'K'], ['Days of job transfer or restriction', fmtNum(T.L), 'L']])}
      \${box('Injury and illness types', ['Injuries', 'Skin disorders', 'Respiratory conditions', 'Poisonings', 'Hearing loss', 'All other illnesses'].map((k, i) => [k, T.M[i], 'M' + (i + 1)]))}
      \${box('Establishment information', [['Establishment', esc(estName())], ['Industry', 'Warehousing and storage (NAICS 493)'], ['Annual average number of employees', h.avg ? fmtNum(h.avg) : '—'], ['Total hours worked by all employees', h.hours ? fmtNum(h.hours) : '—'], ['TRIR (recordables per 100 full-time workers)', trir != null ? trir.toFixed(2) : '—'], ['DART rate', dart != null ? dart.toFixed(2) : '—']])}
    </div>
    <p class="xl-foot">Hours worked and the average number of employees come from the Labor log (regular + OT hours, people with hours each week) for \${esc(st.year)}\${st.facility ? ' in building ' + esc(st.facility) : ''}\${h.weeks ? \` — \${h.weeks} weeks entered\` : ' — no Labor hours entered yet'}. Check them against payroll before certifying. TRIR = recordable cases × 200,000 ÷ hours; DART = cases with days away, restriction or transfer × 200,000 ÷ hours.</p>
    <details class="sf-rules" open><summary>OSHA recordkeeping reminders</summary><ul>
      <li>Enter each recordable case on the OSHA 300 Log and complete a 301 (this report) <b>within 7 calendar days</b> of learning about it.</li>
      <li>Report directly to OSHA: a work-related <b>fatality within 8 hours</b>; an <b>in-patient hospitalization, amputation or loss of an eye within 24 hours</b> (1-800-321-OSHA or osha.gov).</li>
      <li>A company executive certifies the 300A; <b>post it from February 1 to April 30</b> where notices to employees are posted.</li>
      <li>Establishments that must submit electronically (OSHA ITA) send the 300A data <b>by March 2</b> — warehousing establishments with 20 or more employees are generally covered; confirm on osha.gov.</li>
      <li>Keep the 300 Log, 300A and 301 reports for <b>5 years</b> after the year they cover.</li></ul></details>\`;
}

function print300A(rec, h) {
  const T = totals(rec), w = window.open('', '_blank');
  if (!w) return toast('The browser blocked the print window — allow pop-ups for this page', 'bad');
  const r = (k, v) => \`<tr><td>\${k}</td><td class="n">\${v}</td></tr>\`;
  w.document.write(\`<!doctype html><html><head><meta charset="utf-8"><title>OSHA 300A \${esc(st.year)} — \${esc(estName())}</title><style>
    body{font:13px Calibri,Arial,sans-serif;color:#1c232d;margin:28px}h1{font-size:20px;margin:0}h2{font-size:14px;margin:18px 0 6px;border-bottom:3px solid #c0392b;padding-bottom:3px}
    table{border-collapse:collapse;width:100%}td{border:1px solid #c8ced8;padding:5px 8px}.n{text-align:right;font-weight:700;width:120px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    .sig td{height:34px;vertical-align:bottom}.muted{color:#5b6478;font-size:11px}</style></head><body>
    <h1>OSHA Form 300A — Summary of Work-Related Injuries and Illnesses</h1><div class="muted">Year \${esc(st.year)} · \${esc(estName())} · Prepared \${esc(us(todayISO()))} from the Piper Warehouse Operations Dashboard. Use OSHA's official form for the posted copy if required.</div>
    <div class="cols"><div><h2>Number of cases</h2><table>\${r('(G) Total number of deaths', T.G)}\${r('(H) Cases with days away from work', T.H)}\${r('(I) Cases with job transfer or restriction', T.I)}\${r('(J) Other recordable cases', T.J)}</table>
    <h2>Number of days</h2><table>\${r('(K) Days away from work', T.K)}\${r('(L) Days of job transfer or restriction', T.L)}</table>
    <h2>Injury and illness types</h2><table>\${r('(M1) Injuries', T.M[0])}\${r('(M2) Skin disorders', T.M[1])}\${r('(M3) Respiratory conditions', T.M[2])}\${r('(M4) Poisonings', T.M[3])}\${r('(M5) Hearing loss', T.M[4])}\${r('(M6) All other illnesses', T.M[5])}</table></div>
    <div><h2>Establishment information</h2><table>\${r('Establishment name', esc(estName()))}\${r('Industry', 'Warehousing and storage (NAICS 493)')}\${r('Annual average number of employees', h.avg || '')}\${r('Total hours worked by all employees last year', h.hours ? Math.round(h.hours).toLocaleString() : '')}</table>
    <h2>Certification</h2><p class="muted">I certify that I have examined this document and that to the best of my knowledge the entries are true, accurate, and complete.</p>
    <table class="sig"><tr><td>Company executive</td><td></td></tr><tr><td>Title</td><td></td></tr><tr><td>Phone</td><td></td></tr><tr><td>Date</td><td></td></tr></table></div></div>
    <p class="muted">Post from February 1 to April 30. Knowingly falsifying this document may result in a fine.</p></body></html>\`);
  w.document.close(); w.focus(); setTimeout(() => w.print(), 300);
}

export default {
  needs: () => ['incidents', 'otif', 'labor', 'employees'],
  render(p) {
    const s = store.settings;
    if (!st.year) st.year = String(s.reportingYear || new Date().getFullYear());
    if (p.query.tab && ['history', 'osha300', 'osha300a'].includes(p.query.tab)) st.tab = p.query.tab;
    const years = [...new Set([String(s.reportingYear), String(new Date().getFullYear()), st.year, ...store.rows('incidents').map(r => String(yearOf(r.date) || '')).filter(Boolean)])].sort().reverse();
    const yr = scoped(st.year, st.facility), rec = yr.filter(isRec).sort((a, b) => String(a.date).localeCompare(String(b.date)) || String(a.id).localeCompare(String(b.id), undefined, { numeric: true }));
    const h = hoursFor(st.year, st.facility), trir = rate(rec.length, h.hours), dartN = rec.filter(isDart).length, dart = rate(dartN, h.hours);
    const T = totals(rec), facOk = r => !st.facility || String(r.facility) === st.facility;
    const lastRec = store.rows('incidents').filter(r => isRec(r) && facOk(r)).map(r => r.date).filter(isISO).sort().at(-1);
    const since = lastRec ? Math.max(0, Math.round((Date.parse(todayISO()) - Date.parse(lastRec)) / 864e5)) : null;
    const open = store.rows('incidents').filter(r => (r.status || 'Open') !== 'Closed' && facOk(r));
    const wait = otifWaiting().filter(facOk);
    const pastDue = open.filter(r => (r.correctives || []).some(c => c.action && c.done !== 'Done' && c.due && c.due < todayISO())).length;
    const n = t => yr.filter(r => (r.types || []).includes(t)).length;
    const tiles = [
      kpi('Reports · ' + st.year, fmtNum(yr.length), \`\${n('Near Miss')} near misses · \${n('Unsafe Condition') + n('Unsafe Act')} unsafe acts / conditions\`),
      kpi('OSHA recordable cases', fmtNum(rec.length), trir != null ? \`TRIR \${trir.toFixed(2)} per 100 full-time workers\` : 'TRIR needs Labor log hours', rec.length ? 'bad' : 'good'),
      kpi('DART cases', fmtNum(dartN), dart != null ? \`DART rate \${dart.toFixed(2)}\` : 'days away, restricted or transferred', dartN ? 'bad' : ''),
      kpi('Days away · restricted', \`\${fmtNum(T.K)} <small>/ \${fmtNum(T.L)}</small>\`, 'calendar days, capped at 180 per case'),
      kpi('Open reports', fmtNum(open.length), \`\${pastDue ? \`\${pastDue} with overdue actions · \` : ''}\${wait.length} missing a required report\`, open.length || wait.length ? 'warn' : 'good'),
      kpi('Days since last recordable', since == null ? '—' : fmtNum(since), lastRec ? \`last case \${us(lastRec)}\` : 'none recorded', since == null || since >= 90 ? 'good' : ''),
    ];
    const waitCard = wait.length ? \`<section class="card sf-wait" aria-labelledby="sf-wait-h"><div class="card-head"><h2 id="sf-wait-h">Missing a required report — \${wait.length} Recordable Incident\${wait.length === 1 ? '' : 's'} on the OTIF Log</h2><span class="muted small">The Safety Incident / Near Miss Report (\${FORM_NO}) is required for every recordable incident. Fill it out now; it also goes on the OSHA 300 Log within 7 days.</span></div>
      \${wait.map(o => \`<div class="sf-wait-row"><span class="mono"><a href="#/log/otif?ids=\${encodeURIComponent(o.id)}">\${esc(o.id)}</a></span><span>\${esc(us(o.date))}</span><span>\${esc(o.facility || '')}</span><span class="grow clip-in" title="\${esc(o.description || '')}">\${esc(o.responsible || '')}\${o.description ? ' — ' + esc(o.description) : ''}</span>
        \${store.can('edit') ? \`<button type="button" class="btn primary small" data-fill="\${esc(o.id)}">Fill out the form</button>\` : ''}</div>\`).join('')}</section>\` : '';
    const tab = (k, l) => \`<button type="button" role="tab" aria-selected="\${st.tab === k}" class="\${st.tab === k ? 'on' : ''}" data-tab="\${k}">\${l}</button>\`;
    const body = st.tab === 'osha300' ? log300Tab(rec) : st.tab === 'osha300a' ? summary300ATab(rec, h) : historyTab(filtered());
    return \`<div class="log-xl sf-xl">
      <div class="xl-dash-head log-head">
        <div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;Safety Incidents &amp; OSHA Recordkeeping</h1><p>Every safety incident and near miss on the Safety Incident / Near Miss Report (\${FORM_NO}), with OSHA 301 details, the OSHA 300 Log and the 300A Summary. A Recordable Incident on the OTIF Log asks for this report. Click a row to open, update or email a report.</p></div>
        <div class="xl-meta"><b>Year:</b><select data-year aria-label="Year">\${years.map(y => \`<option\${y === st.year ? ' selected' : ''}>\${y}</option>\`).join('')}</select>
          <b>Building:</b><select data-fac aria-label="Building"><option value="">Both buildings</option>\${(s.lists.facilities || []).map(f => \`<option\${f === st.facility ? ' selected' : ''}>\${esc(f)}</option>\`).join('')}</select>
          <span class="sp"></span>\${store.can('edit') ? '<button type="button" class="btn primary" data-new>+ New incident report</button>' : ''}</div>
        <div class="log-insights"><div class="xl-tiles q" style="grid-template-columns:repeat(\${tiles.length}, minmax(0, 1fr))">\${tiles.join('')}</div>
          <div class="log-chart split">\${frame(\`Reports by month &amp; type — \${esc(st.year)}\`, 'ch-sf', 250, 'Safety reports per month stacked by incident type')}\${frame('Reports by category', 'ch-sf-b', 250, 'Safety reports per category, most first')}</div></div>
      </div>
      \${waitCard}
      <div class="sf-tabs" role="tablist" aria-label="Safety views">\${tab('history', 'Incident history')}\${tab('osha300', \`OSHA 300 Log <span class="sf-n">\${rec.length}</span>\`)}\${tab('osha300a', 'OSHA 300A Summary')}</div>
      <section class="card log-card sf-card">\${body}</section></div>\`;
  },
  after(root, p, rerender) {
    const yr = scoped(st.year, st.facility), months = MON.map((m, i) => \`\${st.year}-\${String(i + 1).padStart(2, '0')}\`);
    chart('ch-sf', { type: 'bar', data: { labels: MON, datasets: TYPES.map(t => ({ label: t, data: months.map(m => yr.filter(r => String(r.date).startsWith(m) && (r.types || []).includes(t)).length), backgroundColor: TYPE_COL[t], stack: 's', borderRadius: 1 })) },
      options: { interaction: { mode: 'index', intersect: false }, plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, padding: 14 } }, tooltip: { filter: t => t.parsed.y > 0 } },
        scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, ticks: { precision: 0 }, title: { display: true, text: 'Reports' } } } } });
    const cats = CATEGORIES.map(c => [c, yr.filter(r => (r.categories || []).includes(c)).length]).filter(e => e[1]).sort((a, b) => b[1] - a[1]);
    chart('ch-sf-b', { type: 'bar', data: { labels: cats.map(e => e[0]), datasets: [{ label: 'Reports', data: cats.map(e => e[1]), backgroundColor: '#c0392b', borderRadius: 3, maxBarThickness: 22 }] },
      options: { indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, ticks: { precision: 0 }, grid: { color: '#eef0f4' } }, y: { grid: { display: false } } } } });

    const saved = () => rerender();
    const openById = id => { const r = store.rows('incidents').find(x => x.id === id); if (r) openIncidentForm(r, {}, { onSaved: saved }); };
    $('[data-year]', root)?.addEventListener('change', e => { st.year = e.target.value; rerender(); });
    $('[data-fac]', root)?.addEventListener('change', e => { st.facility = e.target.value; rerender(); });
    $$('[data-new]', root).forEach(b => b.addEventListener('click', () => openIncidentForm(null, {}, { onSaved: saved })));
    $$('[data-tab]', root).forEach(b => b.addEventListener('click', () => { st.tab = b.dataset.tab; if (location.hash.includes('tab=')) location.hash = '#/safety'; else rerender(); }));
    $$('[data-fill]', root).forEach(b => b.addEventListener('click', () => { const o = store.rows('otif').find(r => r.id === b.dataset.fill); if (o) openIncidentForm(null, fromOtif(o), { onSaved: saved, required: true }); }));
    const q = $('[data-q]', root); let t;
    q?.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => { st.q = q.value; st.limit = 200; rerender(); setTimeout(() => { const n = $('#main [data-q]'); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 250); });
    $('[data-status]', root)?.addEventListener('change', e => { st.status = e.target.value; rerender(); });
    $('[data-type]', root)?.addEventListener('change', e => { st.type = e.target.value; rerender(); });
    $('[data-rec]', root)?.addEventListener('change', e => { st.rec = e.target.checked; rerender(); });
    $('[data-clear]', root)?.addEventListener('click', () => { Object.assign(st, { q: '', status: '', type: '', rec: false }); rerender(); });
    $('[data-more]', root)?.addEventListener('click', () => { st.limit += 200; rerender(); });
    for (const tb of $$('.sf-card tbody', root)) {
      tb.addEventListener('click', e => { const tr = e.target.closest('tr[data-id]'); if (tr && !e.target.closest('a')) openById(tr.dataset.id); });
      tb.addEventListener('keydown', e => { const tr = e.target.closest('tr[data-id]'); if (tr && e.key === 'Enter') openById(tr.dataset.id); });
    }
    const rec = yr.filter(isRec).sort((a, b) => String(a.date).localeCompare(String(b.date))), stamp = todayISO();
    $('[data-xlsx]', root)?.addEventListener('click', () => {
      const rows = filtered();
      downloadXLSX(\`Safety Incidents \${stamp}.xlsx\`, 'Safety Incidents', ['Report #', 'Status', 'Date', 'Time', 'Facility', 'Area', 'Exact location', 'Reported by', 'Employee', 'Job title', 'Incident type', 'Category', 'What happened', 'What could have happened', 'Equipment', 'MHE / Trailer / Railcar #', 'Injured', 'Body part', 'Nature of injury', 'OSHA type', 'Treatment', 'OSHA recordable', 'Classification', 'Days away', 'Days restricted', 'Immediate actions', 'Contributing factors', 'Risk level', 'Witnesses', 'Corrective actions', 'Supervisor', 'Date closed', 'OTIF ref', 'Files'],
        rows.map(r => [r.id, r.status || 'Open', r.date, r.time, r.facility, r.area === 'Other' ? r.areaOther || 'Other' : r.area, r.location, r.reportedBy, r.employee, r.jobTitle, typesText(r), otherText(r.categories, r.categoryOther), r.whatHappened, r.couldHappen,
          (r.equipment || []).join(', '), r.equipmentNo, r.injured === 'Y' ? 'Yes' : r.injured === 'N' ? 'No' : '', r.bodyPart, r.injuryNature, r.oshaType, r.treatment, r.recordable === 'TBD' ? 'Not yet determined' : r.recordable, classify(r),
          r.daysAway === '' || r.daysAway == null ? '' : cap(r.daysAway), r.daysRestricted === '' || r.daysRestricted == null ? '' : cap(r.daysRestricted), otherText(r.actions, r.actionsOther), otherText(r.factors, r.factorOther), r.risk,
          (r.witnesses || []).map(w => w.name).filter(Boolean).join(', '), (r.correctives || []).map(c => \`\${c.action}\${c.responsible ? \` (\${c.responsible})\` : ''}\${c.due ? \` due \${c.due}\` : ''} – \${c.done || 'Open'}\`).join('\\n'), r.supName, r.dateClosed, r.otifId, r.files || 0]));
      toast(\`Exported \${rows.length} report\${rows.length === 1 ? '' : 's'} to Excel\`);
    });
    $('[data-x300]', root)?.addEventListener('click', () => {
      downloadXLSX(\`OSHA 300 Log \${st.year}\${st.facility ? ' ' + st.facility : ''}.xlsx\`, \`OSHA 300 \${st.year}\`, ['(A) Case no.', '(B) Employee name', '(C) Job title', '(D) Date of injury', '(E) Where the event occurred', '(F) Describe injury or illness', '(G) Death', '(H) Days away', '(I) Job transfer / restriction', '(J) Other recordable', '(K) Days away from work', '(L) Days of transfer / restriction', '(M1) Injury', '(M2) Skin disorder', '(M3) Respiratory condition', '(M4) Poisoning', '(M5) Hearing loss', '(M6) All other illnesses'],
        rec.map(r => { const c = classify(r), ty = r.oshaType || 'Injury', x = b => (b ? 'X' : ''); return [caseNo(r), r.privacyCase === 'Y' ? 'Privacy Case' : r.employee, r.jobTitle, r.date, where(r), describe(r), x(c === 'Death'), x(c === 'Days away from work'), x(c === 'Job transfer or restriction'), x(c === 'Other recordable case'), cap(r.daysAway), cap(r.daysRestricted), ...OSHA_TYPES.map(o => x(o === ty))]; }));
    });
    $('[data-x300a]', root)?.addEventListener('click', () => {
      const T = totals(rec), h = hoursFor(st.year, st.facility);
      downloadXLSX(\`OSHA 300A \${st.year}\${st.facility ? ' ' + st.facility : ''}.xlsx\`, \`OSHA 300A \${st.year}\`, ['Item', 'Value'], [['Establishment', estName()], ['Year', +st.year], ['(G) Total deaths', T.G], ['(H) Cases with days away', T.H], ['(I) Cases with job transfer or restriction', T.I], ['(J) Other recordable cases', T.J], ['(K) Days away from work', T.K], ['(L) Days of job transfer or restriction', T.L],
        ...OSHA_TYPES.map((t, i) => [\`(M\${i + 1}) \${t}\`, T.M[i]]), ['Annual average number of employees', h.avg], ['Total hours worked', Math.round(h.hours)]]);
    });
    $('[data-print300a]', root)?.addEventListener('click', () => print300A(rec, hoursFor(st.year, st.facility)));
    // Links: #/safety?open=INC-0001 (global search), ?new=1, ?otif=OTIF-0042 (fill out the report for that entry).
    const clean = () => history.replaceState(null, '', '#/safety');
    if (p.query.open) { clean(); openById(p.query.open); }
    else if (p.query.otif && store.can('edit')) { clean(); const o = store.rows('otif').find(r => r.id === p.query.otif); if (o) openIncidentForm(null, fromOtif(o), { onSaved: saved, required: true }); }
    else if (p.query.new && store.can('edit')) { clean(); openIncidentForm(null, {}, { onSaved: saved }); }
  },
};`]);

// ===================== views/scorecards.js =====================
ATL_SRC.push(['@atl/views/scorecards.js', 0, `// Damage Scorecard + Attendance Scorecard.
import { store } from '@atl/store.js';
import { damageScorecard, attendanceScorecard } from '@atl/calc.js';
import { esc, fmtMoney, fmtMon, fmtNum, fmtPct, isISO, norm, todayISO } from '@atl/util.js';
import { kpi, chart, chartBox, jumpBar, wireJumpBar } from '@atl/ui.js';

// Shared look with the KPI dashboards: cream tiles, framed charts, the same chart colors.
const X = { dark: '#222b36', red: '#c0392b', tan: '#c0904d', blue: '#4d6f99', grey: '#9aa3b8' };
const tiles = list => \`<div class="xl-tiles q" style="grid-template-columns:repeat(\${list.length}, minmax(0, 1fr))">\${list.join('')}</div>\`;
const scChart = (title, id, h, aria) => \`<div class="xl-chart"><h4>\${title}</h4>\${chartBox(id, h, aria)}</div>\`;
const legend = { position: 'bottom', labels: { boxWidth: 12, padding: 14 } };

// ---------- Damage Scorecard, laid out like the workbook tab ----------
// Workbook number formats: zero shows as "-", money has no cents, 6021 tons keep one decimal.
const dash = (v, f) => (v === '' || v == null ? '' : v === 0 ? '-' : f(v));
const int = v => dash(v, x => fmtNum(x));
const tons = v => dash(v, x => fmtNum(x, 1));
const usd = v => dash(v, x => fmtMoney(x));
const rate2 = v => dash(v, x => fmtNum(x, 2));
const pct0 = (n, of) => (of ? fmtPct(n / of, 0) : '-');
const vsCell = v => \`<td class="\${v === 'On Target' ? 'ok' : v === 'Above' ? 'over' : ''}">\${esc(v)}</td>\`;
const monthLabel = iso => \`\${fmtMon(iso)} \${iso.slice(0, 4)}\`;

function damageMonthly(title, m, unitLabel, thr) {
  const line = (label, r, cls = '') => \`<tr\${cls ? \` class="\${cls}"\` : ''}><td class="lbl">\${label}</td><td>\${int(r.n)}</td><td>\${int(r.piper)}</td><td>\${int(r.qty)}</td>
    <td>\${usd(r.value)}</td><td>\${int(r.openClaims)}</td><td>\${thr(r.through)}</td><td>\${rate2(r.rate)}</td>\${vsCell(r.vs)}</tr>\`;
  return \`<div><div class="ds-sub">\${esc(title)}</div><div class="ds-scroll"><table class="ds">
    <thead><tr><th class="lbl">Month</th><th>Incidents</th><th>Piper-Caused</th><th>Qty Damaged</th><th>Est. $ Value</th><th>Open Claims</th><th>\${unitLabel}</th><th>Rate per 10,000</th><th>vs. Target</th></tr></thead>
    <tbody>\${m.rows.map(r => line(monthLabel(r.month), r)).join('')}\${line('YTD', m.ytd, 'tot')}</tbody></table></div></div>\`;
}

function damageSheet(y) {
  const d = damageScorecard(y), [b49, b21, both] = d.buildings;
  const sumRow = (r, thr, cls = '') => \`<tr\${cls ? \` class="\${cls}"\` : ''}><td class="lbl">\${esc(r.label)}</td><td>\${int(r.n)}</td><td>\${int(r.piper)}</td>
    <td>\${r.n ? pct0(r.piper, r.n) : '-'}</td><td>\${usd(r.value)}</td><td>\${int(r.openClaims)}</td><td>\${thr(r.through)}</td><td>\${rate2(r.rate)}</td>\${vsCell(r.vs)}</tr>\`;
  // Breakdown tables get an in-cell bar so the biggest contributors stand out.
  const brk = (label, rows) => {
    const hi = Math.max(1, ...rows.map(r => r.n));
    return \`<div><div class="ds-sub">\${esc(label)} — YTD</div><div class="ds-scroll"><table class="ds"><thead><tr><th class="lbl">\${esc(label)}</th><th>Incidents</th><th>Piper-Caused</th><th>Est. $ Value</th></tr></thead>
    <tbody>\${rows.map(r => \`<tr><td class="lbl">\${esc(r.label)}</td><td class="dbar"><i style="width:\${(r.n / hi) * 100}%"></i><span>\${int(r.n)}</span></td><td>\${int(r.piper)}</td><td>\${usd(r.value)}</td></tr>\`).join('') || '<tr><td colspan="4" class="none">No damage logged.</td></tr>'}</tbody></table></div></div>\`;
  };
  const target = bb => { const t = store.settings['damageTarget' + bb]; return t === '' || t == null ? null : +t; };
  const rateTile = (r, bb, unit) => kpi(\`Rate per 10,000 \${unit} — \${bb}\`, r.rate === '' ? '-' : rate2(r.rate) || '-',
    target(bb) == null ? 'No target set (Settings ▸ Damage targets)' : \`Target: \${fmtNum(target(bb), 2)}\`, r.vs === 'On Target' ? 'good' : r.vs === 'Above' ? 'bad' : '');
  const head = [
    kpi('Damage incidents — YTD', int(both.n) || '-', \`6049: \${fmtNum(b49.n)}&nbsp; | &nbsp;6021: \${fmtNum(b21.n)}\`),
    kpi('Piper-caused', both.n ? pct0(both.piper, both.n) : '-', \`\${fmtNum(both.piper)} of \${fmtNum(both.n)} incidents\`),
    kpi('Est. $ damage — YTD', usd(both.value) || '-', \`Open claims: \${both.openClaims}\`, ''),
    rateTile(b49, '6049', 'pallets'), rateTile(b21, '6021', 'tons'),
  ];
  return jumpBar([['sc-d-sum', 'Summary'], ['sc-d-chart', 'Monthly chart'], ['sc-d-bldg', 'By building'], ['sc-d-month', 'Monthly tables'], ['sc-d-cust', 'By customer & cause'], ['sc-d-type', 'By type & responsible']]) +
  \`<div class="dmg-sc sc-xl">
    <div class="ds-banner" id="sc-d-sum"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;Damage Scorecard</h1>
      <p>Both buildings — calculated from the Damage Log. Rate = damage incidents per 10,000 pallets (6049) or tons (6021) handled, using throughput from the Customer Throughput log.</p></div>
    <div class="ds-meta"><b>Reporting Year:</b><span class="ds-year">\${y}</span><b>Last entry:</b><span class="ds-last">\${usDate(d.lastEntry)}</span>
      <i>Log damages in the Damage Log. Targets: Settings ▸ Damage targets.</i><a class="ds-home" href="#/home">⌂ Home</a></div>
    <div class="sc-tiles">\${tiles(head)}</div>
    <div class="sc-charts" id="sc-d-chart">\${scChart(\`Damage incidents &amp; estimated $ by month — \${y}\`, 'ch-sc-dmg', 280, \`Monthly damage incidents stacked by building with the estimated dollar line, \${y}\`)}</div>
    <div class="ds-title" id="sc-d-bldg">YTD SUMMARY BY BUILDING</div>
    <div class="ds-sum-wrap"><table class="ds ds-sum"><thead><tr><th class="lbl">Building</th><th>Incidents</th><th>Piper-Caused</th><th>% Piper-Caused</th><th>Est. $ Value</th><th>Open Claims</th><th>Throughput</th><th>Rate per 10,000</th><th>vs. Target</th></tr></thead>
      <tbody>\${sumRow(b49, int)}\${sumRow(b21, tons)}\${sumRow(both, () => '', 'tot')}</tbody></table></div>
    <p class="ds-foot">Rates are not combined across buildings because 6049 is measured in pallets and 6021 in tons. Open Claims = Claim Status "Open" or "Filed".</p>
    <div class="ds-pair" id="sc-d-month">\${damageMonthly('MONTHLY — 6049 (pallets)', d.monthly['6049'], 'Pallets Handled', int)}\${damageMonthly('MONTHLY — 6021 (tons)', d.monthly['6021'], 'Tons Handled', tons)}</div>
    <div class="ds-pair" id="sc-d-cust">\${brk('Customer', d.byCustomer)}\${brk('Cause', d.byCause)}</div>
    <div class="ds-pair" id="sc-d-type">\${brk('Damage Type', d.byType)}\${brk('Responsible Party', d.byResponsible)}</div>
  </div>\`;
}

export default {
  needs: () => ['damage', 'throughput', 'attendance', 'recognition', 'labor', 'employees', ...(store.can('confidential') ? ['discipline'] : [])],
  render(p) {
    const y = store.settings.reportingYear, which = p.which || 'attendance';
    const tabs = ''; // switching scorecards is done from the Scorecards ▾ drop-down in the top bar
    if (which === 'damage') return tabs + damageSheet(y);
    return tabs + attendanceSheet(y);
  },
  after(root, p, rerender) {
    // Sortable headers are real buttons, so they work from the keyboard too.
    root.querySelectorAll('[data-att-sort]').forEach(btn => btn.addEventListener('click', () => {
      const k = btn.dataset.attSort;
      sort = sort.k === k ? { k, dir: -sort.dir } : { k, dir: 1 };
      rerender();
      document.querySelector(\`[data-att-sort="\${k}"]\`)?.focus(); // the page was re-drawn, so look it up again
    }));
    root.querySelector('[data-att-show]')?.addEventListener('change', e => { show = e.target.value; rerender(); });
    root.querySelectorAll('[data-att-view]').forEach(b => b.addEventListener('click', () => { attView = b.dataset.attView; rerender(); }));
    // Name search filters rows in place (no re-render, so typing never loses focus).
    const q = root.querySelector('[data-att-q]');
    q?.addEventListener('input', () => {
      search = q.value; const t = norm(search);
      let n = 0;
      root.querySelectorAll('tr[data-name]').forEach(tr => { const hit = !t || tr.dataset.name.includes(t); tr.hidden = !hit; n += hit; });
      const c = root.querySelector('[data-att-count]'); if (c) c.textContent = \`\${n} shown\`;
    });
    if (search && q) q.dispatchEvent(new Event('input'));
    wireJumpBar(root);
    if ((p.which || 'attendance') === 'damage') drawDamage(store.settings.reportingYear);
    else drawAttendance();
  },
};

/** Top employees by occurrences, stacked by type (same tan / red / slate as the dashboards). */
function drawAttendance() {
  const top = [...lastRows].filter(r => r.total > 0).sort((a, b) => b.total - a.total || a.name.localeCompare(b.name)).slice(0, 12);
  chart('ch-sc-att', {
    type: 'bar',
    data: { labels: top.map(r => r.name), datasets: [
      { label: 'Tardies', data: top.map(r => r.tardies), backgroundColor: X.tan, borderRadius: 1 },
      { label: 'Absences', data: top.map(r => r.absences), backgroundColor: X.red, borderRadius: 1 },
      { label: 'Left early', data: top.map(r => r.leftEarly), backgroundColor: X.dark, borderRadius: 1 },
    ] },
    options: { indexAxis: 'y', plugins: { legend, tooltip: { mode: 'index', callbacks: { footer: items => \`Total: \${items.reduce((a, t) => a + t.parsed.x, 0)} · Last 90 days: \${top[items[0].dataIndex].last90}\` } } },
      scales: { x: { stacked: true, beginAtZero: true, title: { display: true, text: 'Occurrences (YTD)' }, ticks: { precision: 0 } }, y: { stacked: true, grid: { display: false }, ticks: { autoSkip: false } } } },
  });
}

/** Damage by month: incidents stacked by building (left) with the estimated $ line (right). */
function drawDamage(y) {
  const d = damageScorecard(y), a = d.monthly['6049'].rows, b = d.monthly['6021'].rows;
  chart('ch-sc-dmg', {
    data: { labels: a.map(r => fmtMon(r.month)), datasets: [
      { type: 'line', label: 'Est. $ damage', data: a.map((r, i) => (r.value || 0) + (b[i].value || 0) || null), borderColor: X.tan, backgroundColor: X.tan, pointBackgroundColor: '#fff', pointBorderColor: X.tan, pointRadius: 4, pointBorderWidth: 2, borderWidth: 2.5, yAxisID: 'y1', spanGaps: true, order: 0 },
      { type: 'bar', label: '6049 incidents', data: a.map(r => r.n), backgroundColor: X.dark, stack: 'n', yAxisID: 'y', order: 1, borderRadius: 1 },
      { type: 'bar', label: '6021 incidents', data: b.map(r => r.n), backgroundColor: X.red, stack: 'n', yAxisID: 'y', order: 1, borderRadius: 1 },
    ] },
    options: { interaction: { mode: 'index', intersect: false },
      plugins: { legend, tooltip: { callbacks: { label: t => \`\${t.dataset.label}: \${t.dataset.yAxisID === 'y1' ? fmtMoney(t.parsed.y) : t.parsed.y}\` } } },
      scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, title: { display: true, text: 'Incidents' }, ticks: { precision: 0 } },
        y1: { position: 'right', beginAtZero: true, grid: { display: false }, title: { display: true, text: 'Est. $' }, ticks: { callback: v => '$' + v.toLocaleString() } } } },
  });
}

// Attendance Scorecard laid out like the workbook tab: dark banner, same columns, same conditional formatting.
const SC_COLS = [
  { k: 'name', label: 'Employee' }, { k: 'status', label: 'Roster Status' }, { k: 'tardies', label: 'Tardies' },
  { k: 'totalLate', label: 'Total Min. Late' }, { k: 'avgLate', label: 'Avg Min. Late' }, { k: 'absences', label: 'Absences' },
  { k: 'unexcused', label: 'Unexcused Absences' }, { k: 'leftEarly', label: 'Left Early' }, { k: 'total', label: 'Total Occurrences' },
  { k: 'last90', label: 'Last 90 Days' }, { k: 'lastOccurrence', label: 'Last Occurrence' }, { k: 'awardsAllTime', label: 'Awards (All-Time)' },
  { k: 'rank', label: 'Rank (Most Occurrences)' },
];
/**
 * VR-18: employees as cards, most recent risk first. Tiers are display only (Settings): Coaching now at scCoach90+
 * occurrences in the last 90 days, Watch at scWatch90+ (the table's existing 5+ highlight). The table stays one click away.
 */
function riskCards(rows) {
  const s = store.settings, coach = +s.scCoach90 || 10, watch = +s.scWatch90 || 5;
  const list = rows.filter(r => r.total || r.last90).sort((a, b) => b.last90 - a.last90 || b.total - a.total);
  const tier = r => (r.last90 >= coach ? ['bad', 'Coaching now'] : r.last90 >= watch ? ['warn', 'Watch'] : ['good', 'OK']);
  const card = r => {
    const [c, l] = tier(r), t = Math.max(1, r.tardies + r.absences + r.leftEarly);
    return \`<a class="risk-card kpi \${c}" href="#/log/attendance?employee=\${encodeURIComponent(r.name)}" title="Open \${esc(r.name)}'s attendance history">
      <div class="kpi-label">\${esc(String(r.name).toUpperCase())}</div>
      <div class="risk-row"><span class="kpi-value">\${r.last90}</span><span class="muted small">in last 90 days · \${r.total} in \${'YTD'}</span></div>
      <div class="risk-mix" aria-hidden="true"><span style="width:\${r.tardies / t * 100}%;background:#c0904d"></span><span style="width:\${r.absences / t * 100}%;background:#c0392b"></span><span style="width:\${r.leftEarly / t * 100}%;background:#16325c"></span></div>
      <div class="kpi-note"><span class="kpi-chip \${c}">\${l}</span>\${r.tardies} tardy · \${r.absences} absent (\${r.unexcused} unexcused) · \${r.leftEarly} left early</div></a>\`;
  };
  const n = k => list.filter(r => tier(r)[1] === k).length;
  return \`<div class="risk-head xl-anchor" id="sc-a-people"><div class="risk-tiers"><span class="pill bad">Coaching now (\${coach}+ in 90 days): \${n('Coaching now')}</span><span class="pill warn">Watch (\${watch}+): \${n('Watch')}</span><span class="pill good">OK: \${n('OK')}</span></div>
      <div class="seg-btns" role="group" aria-label="View"><button type="button" data-att-view="cards" class="\${attView === 'cards' ? 'on' : ''}">Cards</button><button type="button" data-att-view="table" class="\${attView === 'table' ? 'on' : ''}">Table view</button></div></div>
    \${attView === 'cards' ? \`<div class="risk-grid">\${list.map(card).join('') || '<p class="muted">No occurrences this year.</p>'}</div>
      <div class="share-legend" style="margin:8px 0 0"><span><i style="background:#c0904d"></i>Tardy</span><span><i style="background:#c0392b"></i>Absent</span><span><i style="background:#16325c"></i>Left early</span></div>\` : ''}\`;
}
let sort = { k: '', dir: 1 }; // '' = roster order, like the workbook
let show = 'all'; // 'all' | 'current' (Roster Status = Active)
let search = '';
let attView = 'cards'; // VR-18: 'cards' (by recent risk) | 'table'
let lastRows = []; // rows behind the attendance chart
const usDate = iso => (isISO(iso) ? \`\${iso.slice(5, 7)}/\${iso.slice(8, 10)}/\${iso.slice(0, 4)}\` : '');

function attendanceSheet(y) {
  let rows = attendanceScorecard(y);
  // Rank is still calculated across everyone, so it matches the workbook whichever view is chosen.
  if (show === 'current') rows = rows.filter(r => norm(r.status) === 'ACTIVE');
  if (sort.k) {
    const blankLast = v => v === '' || v == null;
    rows = [...rows].sort((a, b) => {
      const x = a[sort.k], z = b[sort.k];
      if (blankLast(x) !== blankLast(z)) return blankLast(x) ? 1 : -1;
      return (typeof x === 'number' && typeof z === 'number' ? x - z : String(x).localeCompare(String(z))) * sort.dir;
    });
  }
  lastRows = rows;
  const maxTotal = Math.max(1, ...rows.map(r => r.total));
  const head = SC_COLS.map(c => {
    const on = sort.k === c.k, aria = on ? (sort.dir > 0 ? 'ascending' : 'descending') : 'none';
    return \`<th aria-sort="\${aria}"\${c.k === 'name' ? ' class="stick"' : ''}><button type="button" class="th-sort" data-att-sort="\${c.k}">\${esc(c.label)}<span aria-hidden="true">\${on ? (sort.dir > 0 ? '▴' : '▾') : '↕'}</span></button></th>\`;
  }).join('');
  const hot = rows.filter(r => r.last90 >= 5).length;
  const sumK = k => rows.reduce((a, r) => a + (+r[k] || 0), 0);
  const late = rows.reduce((a, r) => a + (+r.totalLate || 0), 0), tard = sumK('tardies');
  const summary = [
    kpi('Employees shown', fmtNum(rows.length), show === 'current' ? 'Current employees only' : 'All employees on the roster'),
    kpi(\`Total occurrences — \${y}\`, fmtNum(sumK('total')), \`Tardies \${fmtNum(tard)}&nbsp; | &nbsp;Absences \${fmtNum(sumK('absences'))}&nbsp; | &nbsp;Left early \${fmtNum(sumK('leftEarly'))}\`),
    kpi('Unexcused absences', fmtNum(sumK('unexcused')), \`of \${fmtNum(sumK('absences'))} absences\`),
    kpi('Avg minutes late', tard ? fmtNum(late / tard, 1) : '-', \`\${fmtNum(late)} minutes across \${fmtNum(tard)} tardies\`),
    kpi('5+ in the last 90 days', fmtNum(hot), hot ? 'Highlighted in the table — coaching candidates' : 'Nobody at 5 or more', hot ? 'bad' : 'good'),
  ];
  const body = rows.map(r => {
    const inactive = norm(r.status) !== 'ACTIVE';
    return \`<tr data-name="\${esc(norm(r.name))}">
      <td class="emp stick"><a class="emp-link" href="#/log/attendance?employee=\${encodeURIComponent(r.name)}" title="Open \${esc(r.name)}'s attendance history">\${esc(String(r.name).toUpperCase())}</a></td>
      <td class="\${inactive ? 'off' : ''}">\${esc(r.status)}</td>
      <td>\${r.tardies}</td><td>\${fmtNum(r.totalLate)}</td><td>\${r.avgLate === '' ? '' : fmtNum(r.avgLate, 1)}</td>
      <td>\${r.absences}</td><td>\${r.unexcused}</td><td>\${r.leftEarly}</td>
      <td class="dbar"><i style="width:\${(r.total / maxTotal) * 100}%"></i><span>\${r.total}</span></td>
      <td class="\${r.last90 >= 5 ? 'hot' : ''}">\${r.last90}</td>
      <td>\${usDate(r.lastOccurrence)}</td>
      <td class="\${r.awardsAllTime > 0 ? 'award' : ''}">\${r.awardsAllTime}</td>
      <td>\${r.rank}</td></tr>\`;
  }).join('') || \`<tr><td colspan="\${SC_COLS.length}" class="none">No employees on the roster yet.</td></tr>\`;
  return jumpBar([['sc-a-sum', 'Summary'], ['sc-a-chart', 'Top 12 chart'], ['sc-a-people', 'Employees']]) +
  \`<div class="att-sc sc-xl">
    <div class="sc-banner" id="sc-a-sum"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;Attendance Scorecard</h1><p>Per-employee view for the Reporting Year (Settings). Duplicates excluded. Use for coaching conversations and recognition decisions.</p></div>
    <div class="sc-meta"><b>Reporting Year:</b><span class="sc-year">\${y}</span><i>Rolling 90 days ends \${usDate(todayISO())}</i>
      <label class="sc-filter">Show <select data-att-show aria-label="Which employees to show">
        <option value="all"\${show === 'all' ? ' selected' : ''}>All employees</option>
        <option value="current"\${show === 'current' ? ' selected' : ''}>Current employees</option>
      </select></label></div>
    <div class="sc-tiles">\${tiles(summary)}</div>
    <div class="sc-charts" id="sc-a-chart">\${scChart('Most occurrences — top 12 employees', 'ch-sc-att', Math.max(220, 40 + Math.min(12, rows.filter(r => r.total).length) * 26), \`Top employees by attendance occurrences in \${y}, split into tardies, absences and early departures\`)}</div>
    \${riskCards(rows)}
    <div class="sc-tools" id="sc-a-table"\${attView === 'cards' ? ' hidden' : ''}>
      <input type="search" class="sc-search" data-att-q placeholder="Search employees…" aria-label="Search employees" value="\${esc(search)}">
      <span class="sc-count" data-att-count aria-live="polite">\${rows.length} shown</span>
      <span class="sc-key"><span class="k hot">≥5 in last 90 days</span><span class="k award">Has awards</span><span class="k bar">Total occurrences bar</span><span class="k off">Not on current roster</span></span>
    </div>
    <div class="sc-wrap"\${attView === 'cards' ? ' hidden' : ''}><table class="sc"><thead><tr>\${head}</tr></thead><tbody>\${body}</tbody></table></div>
    <p class="sc-foot">Click any column heading to sort (click again to reverse). Rank counts every employee, so it matches the workbook whichever view is shown. Last 90 Days and Last Occurrence use the whole log.</p>
  </div>\`;
}`]);

// ===================== views/settings.js =====================
ATL_SRC.push(['@atl/views/settings.js', 0, `// Settings & Lists + Rail Settings + Users & roles (admin only).
import { store } from '@atl/store.js';
import { esc, toast, $, $$ } from '@atl/util.js';
import { page, section } from '@atl/ui.js';
import { UNIT_SETS } from '@atl/throughput.js';

const LIST_LABELS = {
  incidentCategories: 'Incident Categories', customers: 'Customers (OTIF / Damage)', facilities: 'Facilities', supervisors: 'Supervisors / Recorded By',
  incidentStatus: 'Incident Status', awardTypes: 'Award Types', rosterStatus: 'Roster Status', damageStage: 'Damage Stage', damageType: 'Damage Type',
  damageCause: 'Damage Cause', damageResponsible: 'Responsible Party (Damage)', damageRecordedBy: 'Recorded By (Damage) — customers, after the supervisors',damageUnit: 'Damage Unit', claimStatus: 'Claim Status',
  disciplineCategories: 'Discipline Categories', disciplineActions: 'Discipline Actions',
};
const ROLES = ['pending', 'viewer', 'supervisor', 'manager', 'admin'];
let users = null;

/** Editable grid. cols: [{key, label, type: text|number|yn|select, options}] */
function grid(name, cols, rows) {
  const input = (c, v) => c.type === 'yn' || c.type === 'select'
    ? \`<select data-k="\${c.key}">\${(c.options || ['Y', 'N']).map(o => \`<option \${String(o) === String(v ?? '') ? 'selected' : ''}>\${esc(o)}</option>\`).join('')}</select>\`
    : \`<input data-k="\${c.key}" type="\${c.type === 'number' ? 'number' : 'text'}" step="any" value="\${esc(v ?? '')}">\`;
  return \`<div class="table-wrap"><table class="grid entry" data-grid="\${name}"><thead><tr>\${cols.map(c => \`<th>\${c.label}</th>\`).join('')}<th></th></tr></thead><tbody>
    \${rows.map(r => \`<tr>\${cols.map(c => \`<td>\${input(c, r[c.key])}</td>\`).join('')}<td><button type="button" class="icon-btn" data-del-row title="Remove">✕</button></td></tr>\`).join('')}
    </tbody></table></div><button type="button" class="btn ghost small" data-add-row="\${name}">+ Add row</button>
    <template data-tpl="\${name}"><tr>\${cols.map(c => \`<td>\${input(c, c.type === 'yn' ? 'Y' : '')}</td>\`).join('')}<td><button type="button" class="icon-btn" data-del-row>✕</button></td></tr></template>\`;
}
function readGrid(root, name, cols) {
  return $$(\`[data-grid="\${name}"] tbody tr\`, root).map(tr => Object.fromEntries(cols.map(c => {
    const v = $(\`[data-k="\${c.key}"]\`, tr).value.trim();
    return [c.key, c.type === 'number' ? (v === '' ? null : +v) : v];
  }))).filter(r => Object.values(r).some(v => v !== '' && v != null));
}

const ITYPE = [{ key: 'name', label: 'Incident Type' }, { key: 'counts', label: 'Counts in Order Accuracy %?', type: 'yn' }, { key: 'definition', label: 'Definition' }];
const TPC = () => [{ key: 'name', label: 'Customer' }, { key: 'building', label: 'Building', type: 'select', options: store.settings.lists.facilities },
  { key: 'units', label: 'Units (blank = building unit)', type: 'select', options: ['', ...Object.keys(UNIT_SETS)] }, { key: 'aliases', label: 'Also known as (comma-separated)' },
  { key: 'active', label: 'Active', type: 'yn' }];
const HRC = [{ key: 'counter', label: 'HR Counter Name' }, { key: 'countsAs', label: 'Counts As', type: 'select', options: ['Regular', 'OT', 'Ignore'] }];
const RAILC = () => [{ key: 'name', label: 'Customer' }, { key: 'freeDays', label: 'Free Days (business)', type: 'number' }, { key: 'rate', label: 'Demurrage Rate ($/day)', type: 'number' }, { key: 'building', label: 'Building', type: 'select', options: store.settings.lists.facilities }];

// Labor productivity targets (dashboards ▸ Labor Productivity). Higher is better.
const PROD_KEYS = ['6049', '6021'].flatMap(b => {
  const u = b === '6049' ? 'Pallets' : 'Tons';
  return [
    [\`prodTargetOp\${b}\`, \`\${b} — \${u} / hour, operators only (target)\`, 'On Target at or above this. Operator hours only (w/o clerical).'],
    [\`prodCloseOp\${b}\`, \`\${b} — \${u} / hour, operators only (close threshold)\`, 'At or above this but under the target = Close (orange → yellow). Under it = Below (red).'],
    [\`prodTargetAll\${b}\`, \`\${b} — \${u} / hour, all hours (target)\`, 'On Target at or above this. Every hour, clerical included.'],
    [\`prodCloseAll\${b}\`, \`\${b} — \${u} / hour, all hours (close threshold)\`, 'At or above this but under the target = Close. Under it = Below.'],
  ];
});

export default {
  needs: () => [],
  render() {
    if (!store.can('admin')) return page('Settings', 'Admin access is needed to change settings.');
    const s = store.settings, r = store.rail;
    const num = (k, label, v, note = '', step = 'any') => \`<label class="field"><span>\${label}</span><input data-s="\${k}" type="number" step="\${step}" value="\${v ?? ''}">\${note ? \`<small>\${note}</small>\` : ''}</label>\`;
    const general = \`<div class="form-grid">
      \${num('reportingYear', 'Reporting Year', s.reportingYear, 'Dashboard and scorecard YTD figures use this year.', '1')}
      <label class="field"><span>Default Shift Start</span><input data-s="defaultShiftStart" type="time" value="\${esc(s.defaultShiftStart)}"><small>Used when Scheduled Start and the employee's shift start are blank.</small></label>
      <label class="field"><span>6021 manager</span><input data-s="manager6021" type="text" value="\${esc(s.manager6021 || '')}"><small>Manager Name on the Call-Off / Tardy form for 6021 employees (unless the employee has their own Reports To).</small></label>
      <label class="field"><span>6049 manager</span><input data-s="manager6049" type="text" value="\${esc(s.manager6049 || '')}"><small>Manager Name on the Call-Off / Tardy form for 6049 employees (unless the employee has their own Reports To).</small></label>
      \${num('orderAccuracyTarget', 'Order Accuracy Target (%)', +(s.orderAccuracyTarget * 100).toFixed(2))}
      \${num('attendanceTarget', 'Attendance Rate Target (%)', +(s.attendanceTarget * 100).toFixed(2))}
      \${num('disciplineMonths', 'Discipline Active Period (months)', s.disciplineMonths, 'Write-ups older than this drop off Prior Active Actions.', '1')}
      \${num('salariedHours', 'Salaried standard weekly hours', s.salariedHours)}
      \${num('damageTarget6049', '6049 — Damage incidents per 10,000 pallets (target)', s.damageTarget6049, 'Blank = no target. Lower is better.')}
      \${num('damageTarget6021', '6021 — Damage incidents per 10,000 tons (target)', s.damageTarget6021, 'Blank = no target. Lower is better.')}
      \${PROD_KEYS.map(([k, label, note]) => num(k, label, s[k], note)).join('')}
      \${num('otMinRegHours', 'Individual OT chart — grey under this many regular hours', s.otMinRegHours, 'Display only: people with fewer regular hours are shown in grey so a small-hours outlier is not read as the biggest OT problem.', '1')}
      \${num('scWatch90', 'Attendance Scorecard — “Watch” at this many occurrences in 90 days', s.scWatch90, 'Display only (the table already highlights 5+).', '1')}
      \${num('scCoach90', 'Attendance Scorecard — “Coaching now” at this many occurrences in 90 days', s.scCoach90, 'Display only.', '1')}
    </div>\`;
    const lists = \`<div class="lists">\${Object.entries(LIST_LABELS).map(([k, l]) => \`<label class="field"><span>\${l}</span><textarea data-list="\${k}" rows="6">\${esc((s.lists[k] || []).join('\\n'))}</textarea></label>\`).join('')}</div><p class="muted small">One item per line. These feed the dropdowns.</p>\`;
    const userBlock = users
      ? \`<div class="table-wrap"><table class="grid"><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody>\${users.map(u => \`<tr><td>\${esc(u.name || '')}</td><td>\${esc(u.email || '')}</td><td><select data-uid="\${esc(u.id)}" \${u.id === store.user.uid ? 'disabled' : ''}>\${ROLES.map(x => \`<option \${x === u.role ? 'selected' : ''}>\${x}</option>\`).join('')}</select></td></tr>\`).join('')}</tbody></table></div>
         <p class="muted small"><b>viewer</b> sees dashboards and logs · <b>supervisor</b> adds/edits entries · <b>manager</b> also deletes and sees the Disciplinary Log &amp; attendance reasons · <b>admin</b> also manages settings, employees and users. New sign-ins start as <b>pending</b>.</p>\`
      : '<p class="muted">Loading users…</p>';

    return page('Settings & Lists', 'Targets, dropdown lists and masters. Save each block after editing.') +
      \`<form data-settings-form>\` +
      section('General & targets', general) +
      section('Incident types', grid('itypes', ITYPE, s.incidentTypes.map(t => ({ ...t, counts: t.counts ? 'Y' : 'N' })))) +
      section('Dropdown lists', lists) +
      section('Throughput customers (Weekly Entry)', grid('tpc', TPC(), s.throughputCustomers) + '<p class="muted small">Units = what the customer reports each week (each gets Inbound and Outbound on Weekly Entry). The building\\'s unit — pallets in 6049, tons in 6021 — is what totals and the damage rate use. Also known as: other spellings used in files or old entries (e.g. Nexus, WestRock, UPM); they all count as this customer.</p>') +
      section('HR time export — counter mapping', grid('hrc', HRC, s.hrCounters) + '<p class="muted small">A counter in the HR file that is not listed here shows as Unmapped on Weekly Entry. Use Ignore for counters such as "_FLSA Overtime" that duplicate other hours.</p>') +
      \`<div class="sticky-save"><button class="btn primary" type="submit">Save settings</button></div></form>\` +
      \`<form data-rail-form>\` +
      section('Rail settings', \`<div class="form-grid">\${\`<label class="field"><span>Open-car window (days)</span><input data-r="openCarWindowDays" type="number" value="\${r.openCarWindowDays}"><small>Cars with no release date and a CP date older than this are flagged and drop out of "on hand".</small></label>\`}
        <label class="field"><span>Turn charge ($ per turned car)</span><input data-r="turnCharge" type="number" step="any" value="\${r.turnCharge ?? 500}"><small>Charged for each car with Turn = Y; shows in the rail Accessorial charges.</small></label></div>\` + grid('railc', RAILC(), r.customers) +
        '<div class="sticky-save"><button class="btn primary" type="submit">Save rail settings</button></div>') + \`</form>\` +
      section('Employees', '<p>The roster lives in its own table. <a class="btn ghost small" href="#/log/employees">Open Employee Roster ›</a></p>') +
      (store.demo ? '' : section('Users & roles', userBlock)) +
      section('Import from Excel', '<p>Load (or reload) everything from the Rail OTIF KPI Dashboard workbook. <a class="btn ghost small" href="#/import">Open importer ›</a></p>');
  },

  after(root, p, rerender) {
    if (!store.can('admin')) return;
    if (!users && !store.demo) store.listUsers().then(u => { users = u.sort((a, b) => (a.email || '').localeCompare(b.email || '')); rerender(); }).catch(e => toast(e.message, 'bad'));
    root.addEventListener('click', e => {
      if (e.target.matches('[data-del-row]')) e.target.closest('tr').remove();
      const add = e.target.dataset.addRow;
      if (add) $(\`[data-grid="\${add}"] tbody\`, root).appendChild($(\`template[data-tpl="\${add}"]\`, root).content.cloneNode(true));
    });
    $('[data-settings-form]', root).addEventListener('submit', async e => {
      e.preventDefault();
      const v = k => $(\`[data-s="\${k}"]\`, root).value.trim();
      const n = k => (v(k) === '' ? null : +v(k));
      const data = {
        ...stripDefaults(store.settings),
        reportingYear: n('reportingYear'), defaultShiftStart: v('defaultShiftStart'), manager6021: v('manager6021'), manager6049: v('manager6049'),
        orderAccuracyTarget: n('orderAccuracyTarget') / 100, attendanceTarget: n('attendanceTarget') / 100,
        disciplineMonths: n('disciplineMonths'), salariedHours: n('salariedHours'),
        damageTarget6049: n('damageTarget6049'), damageTarget6021: n('damageTarget6021'),
        ...Object.fromEntries(PROD_KEYS.map(([k]) => [k, n(k)])),
        otMinRegHours: n('otMinRegHours'), scWatch90: n('scWatch90'), scCoach90: n('scCoach90'),
        incidentTypes: readGrid(root, 'itypes', ITYPE).map(t => ({ ...t, counts: t.counts === 'Y' })),
        throughputCustomers: readGrid(root, 'tpc', TPC()),
        hrCounters: readGrid(root, 'hrc', HRC),
        lists: Object.fromEntries($$('[data-list]', root).map(t => [t.dataset.list, t.value.split('\\n').map(x => x.trim()).filter(Boolean)])),
      };
      try { await store.saveConfig('settings', data); toast('Settings saved'); } catch (err) { toast(err.message, 'bad'); }
    });
    $('[data-rail-form]', root).addEventListener('submit', async e => {
      e.preventDefault();
      const data = { ...store.rail, openCarWindowDays: +$('[data-r="openCarWindowDays"]', root).value || 30, turnCharge: $('[data-r="turnCharge"]', root).value === '' ? 500 : +$('[data-r="turnCharge"]', root).value, customers: readGrid(root, 'railc', RAILC()) };
      try { await store.saveConfig('rail', data); toast('Rail settings saved'); } catch (err) { toast(err.message, 'bad'); }
    });
    $$('[data-uid]', root).forEach(sel => sel.addEventListener('change', async e => {
      try { await store.setUserRole(e.target.dataset.uid, e.target.value); toast('Role updated'); users = null; } catch (err) { toast(err.message, 'bad'); }
    }));
  },
};

const stripDefaults = s => JSON.parse(JSON.stringify(s));`]);

// ===================== views/writeup.js =====================
ATL_SRC.push(['@atl/views/writeup.js', 0, `// Write-up dialog (Disciplinary Log ▸ New write-up): fill in the Employee Corrective Action / Write-Up form in the app,
// save it to the Disciplinary Log, and create an Outlook email with the filled-in Word form attached.
import { store } from '@atl/store.js';
import { derive, managerOf } from '@atl/calc.js';
import { esc, fmtDate, norm, toast, downloadBlob } from '@atl/util.js';
import { writeUpDocx, writeUpFileName, LEVELS, VIOLATIONS, LEVEL_TO_ACTION, VIOLATION_TO_CATEGORY } from '@atl/forms/writeup.js';
import { emlDraft } from '@atl/forms/email.js';
import { archiveSent, employeeBuilding } from '@atl/forms/archive.js';
import { DOCX } from '@atl/forms/docx.js';
import { suggestSOPs, allSOPRules, allSOPDocs, sopCitation, sopTag } from '@atl/forms/sopmatch.js';

const todayISO = () => { const d = new Date(); return \`\${d.getFullYear()}-\${String(d.getMonth() + 1).padStart(2, '0')}-\${String(d.getDate()).padStart(2, '0')}\`; };
const us = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(0, 4)}\` : '');
const empByName = name => store.rows('employees').find(e => e.name && norm(e.name) === norm(name));
/** Earlier write-ups for this employee from the Disciplinary Log, newest first: "1/15/2026 – Written Warning (Active)". */
const priorFor = (name, before) => derive('discipline').filter(r => norm(r.employee) === norm(name) && r.date && r.date < before)
  .sort((a, b) => b.date.localeCompare(a.date)).map(r => \`\${us(r.date)} – \${r.action || 'Action'}\${r.status ? \` (\${r.status})\` : ''}\`);

/** Open the write-up dialog. rerender: redraw the Disciplinary Log after saving. */
export function openWriteUp(rerender) {
  const emps = store.rows('employees').filter(e => e.name);
  const active = emps.filter(e => norm(e.rosterStatus) === 'ACTIVE').sort((a, b) => a.name.localeCompare(b.name));
  const former = emps.filter(e => norm(e.rosterStatus) !== 'ACTIVE').sort((a, b) => a.name.localeCompare(b.name));
  const opt = e => \`<option value="\${esc(e.name)}">\${esc(e.name)}</option>\`;
  document.querySelector('.wu-back')?.remove();
  const el = document.createElement('div');
  el.className = 'modal-back wu-back';
  el.innerHTML = \`<form class="modal wu-pop" novalidate role="dialog" aria-modal="true" aria-labelledby="wu-title">
    <div class="modal-head"><h2 id="wu-title">✎ Employee corrective action / write-up</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
    <p class="muted small">Fills in the company Write-Up form. Employee Comments and the signatures are left blank for the meeting with the employee. Confidential — managers &amp; HR only.</p>

    <fieldset class="wu-sec"><legend>Employee information</legend><div class="wu-grid">
      <label class="wide">Employee name <select name="name" required><option value="">— choose —</option><optgroup label="Active roster">\${active.map(opt).join('')}</optgroup>\${former.length ? \`<optgroup label="Not on current roster">\${former.map(opt).join('')}</optgroup>\` : ''}</select></label>
      <label>Employee ID <input name="employeeId" type="text"></label>
      <label>Job title <input name="jobTitle" type="text" placeholder="e.g. Warehouse Associate"></label>
      <label>Shift <select name="shift"><option>First</option><option>Second</option><option>Third</option></select></label>
      <label>Facility / location <input name="facility" type="text"></label>
      <label>Supervisor / manager <input name="manager" type="text"></label>
      <label>Date of write-up <input name="date" type="date" value="\${todayISO()}" required></label>
      <label>Date of incident <input name="incidentDate" type="date"></label>
      <label>Time of incident <input name="incidentTime" type="time"></label>
    </div></fieldset>

    <fieldset class="wu-sec"><legend>Level of corrective action <small>(check one)</small></legend>
      <div class="wu-chips" role="radiogroup">\${LEVELS.map((l, i) => \`<label><input type="radio" name="level" value="\${l}"\${i ? '' : ' checked'}> \${l}</label>\`).join('')}
        <label class="wu-days" hidden>Days <input name="suspensionDays" type="number" min="0.5" step="0.5" value="1"></label></div></fieldset>

    <fieldset class="wu-sec"><legend>Type of violation <small>(check all that apply)</small></legend>
      <div class="wu-chips">\${VIOLATIONS.map(v => \`<label><input type="checkbox" name="violations" value="\${v}"> \${v}</label>\`).join('')}</div>
      <label class="wu-other" hidden>Other — describe <input name="otherViolation" type="text"></label></fieldset>

    <fieldset class="wu-sec"><legend>Incident summary</legend>
      <textarea name="summary" rows="5" required placeholder="What happened — who, what, when, where. Stick to facts."></textarea></fieldset>

    <fieldset class="wu-sec"><legend>Policy / procedure violated &amp; prior corrective actions</legend><div class="wu-grid">
      <label class="wide">Suggested SOP / policy violated <span class="muted small" data-sop-hint>— write the incident summary above and matching SOP rules appear here</span>
        <select name="sopPick" aria-describedby="wu-sop-help"><option value="">— choose an SOP rule to add —</option></select></label>
      <label class="wide">Policy / SOP violated <textarea name="policy" rows="3" placeholder="Choose from the list above, or type a handbook section / SOP number and title"></textarea></label>
      <p class="wide muted small" id="wu-sop-help">Suggestions come from the Employee Handbook, the safety and operating SOPs, the SQF food-safety program (GMP, allergens, pest control, sanitation, food defense…) and the building placards — everything in SOP/Documents — matched to the incident summary. Each one you choose is added on its own line; edit freely.</p>
      <div class="wide wu-prior"><span>Prior related actions</span>
        <label><input type="radio" name="prior" value="None" checked> None</label><label><input type="radio" name="prior" value="Yes"> Yes</label>
        <input name="priorText" type="text" placeholder="Date(s) / level" aria-label="Prior actions — dates and levels"></div>
      <p class="wide muted small wu-prior-note" data-prior-note></p></div></fieldset>

    <fieldset class="wu-sec"><legend>Disciplinary action &amp; expected improvement</legend>
      <textarea name="action" rows="3" placeholder="The action taken and what must change going forward."></textarea></fieldset>

    <div class="modal-foot"><div class="wu-opts">
        <label><input type="checkbox" name="save" checked> Save to the Disciplinary Log</label>
        <label><input type="checkbox" name="email" checked> Create an <b>Outlook email</b> with the write-up attached</label></div>
      <div><button type="button" class="btn ghost" data-close>Cancel</button><button type="submit" class="btn primary">Create write-up</button></div></div>
  </form>\`;
  document.body.appendChild(el);
  const form = el.querySelector('form'), f = form.elements;
  const close = () => el.remove();
  el.addEventListener('click', e => { if (e.target === el || e.target.closest('[data-close]')) close(); });
  el.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });

  // Choosing the employee fills in ID, facility, manager and their earlier write-ups from the Disciplinary Log.
  const fillFromEmployee = () => {
    const e = empByName(f.name.value); if (!e) return;
    f.employeeId.value = e.hrId || '';
    f.employeeId.placeholder = e.hrId ? '' : 'Not on file yet — saved at the next HR timesheet import';
    f.facility.value = e.homeFacility || e.defaultBuilding || '';
    f.manager.value = managerOf(e);
    const prior = priorFor(e.name, f.date.value || todayISO());
    form.querySelector(\`[name="prior"][value="\${prior.length ? 'Yes' : 'None'}"]\`).checked = true;
    f.priorText.value = prior.join('; ');
    form.querySelector('[data-prior-note]').textContent = prior.length ? \`Found \${prior.length} earlier entr\${prior.length === 1 ? 'y' : 'ies'} in the Disciplinary Log — edit if needed.\` : 'No earlier entries in the Disciplinary Log.';
  };
  // SOP drop-down: best matches for the incident summary (and violation types) first, then every rule by document.
  const rules = allSOPRules();
  const ruleOpt = (r, tag = '') => \`<option value="\${r.i}">\${esc(\`\${tag}\${sopTag(r.doc)} · \${r.section} — \${r.text}\`.slice(0, 190))}</option>\`;
  const fullList = allSOPDocs().map((doc, d) => \`<optgroup label="All rules — \${esc([doc.number, doc.short || doc.title].filter(Boolean).join(' '))}">\${rules.filter(r => r.d === d).map(r => ruleOpt(r)).join('')}</optgroup>\`).join('');
  const refreshSOPs = () => {
    const text = [f.summary.value, ...[...form.querySelectorAll('[name="violations"]:checked')].map(c => c.value), f.otherViolation.value].join(' ');
    const hits = suggestSOPs(text, 8), hint = form.querySelector('[data-sop-hint]');
    f.sopPick.innerHTML = \`<option value="">\${hits.length ? \`— \${hits.length} suggested rule\${hits.length === 1 ? '' : 's'} — choose one to add —\` : '— choose an SOP rule to add —'}</option>\`
      + (hits.length ? \`<optgroup label="Suggested from the incident summary (best match first)">\${hits.map(h => ruleOpt(h.rule, h.score > 4 ? '★ ' : '')).join('')}</optgroup>\` : '') + fullList;
    hint.textContent = !f.summary.value.trim() ? '— write the incident summary above and matching SOP rules appear here'
      : hits.length ? \`— \${hits.length} suggestion\${hits.length === 1 ? '' : 's'} from the summary (★ = strong match)\` : '— no close match in the SOPs; choose from the full list or type it in';
  };
  let sopTimer;
  f.summary.addEventListener('input', () => { clearTimeout(sopTimer); sopTimer = setTimeout(refreshSOPs, 300); });
  f.sopPick.addEventListener('change', () => {
    const r = rules[+f.sopPick.value]; if (!r) return;
    const line = sopCitation(r), cur = f.policy.value.trim();
    if (!cur.split('\\n').includes(line)) f.policy.value = cur ? \`\${cur}\\n\${line}\` : line;
    f.sopPick.value = '';
    f.policy.style.height = 'auto'; f.policy.style.height = Math.min(220, f.policy.scrollHeight + 4) + 'px'; // grow to show every line
  });
  refreshSOPs();

  form.addEventListener('change', e => {
    if (e.target.name === 'name' || e.target.name === 'date') fillFromEmployee();
    if (e.target.name === 'violations' || e.target.name === 'otherViolation') refreshSOPs();
    form.querySelector('.wu-days').hidden = form.querySelector('[name="level"]:checked')?.value !== 'Suspension';
    form.querySelector('.wu-other').hidden = !form.querySelector('[name="violations"][value="Other"]').checked;
  });

  form.addEventListener('submit', async e => {
    e.preventDefault();
    const w = {
      name: f.name.value, employeeId: f.employeeId.value.trim(), jobTitle: f.jobTitle.value.trim(), shift: f.shift.value,
      facility: f.facility.value.trim(), manager: f.manager.value.trim(), date: f.date.value, incidentDate: f.incidentDate.value, incidentTime: f.incidentTime.value,
      level: form.querySelector('[name="level"]:checked')?.value, suspensionDays: f.suspensionDays.value,
      violations: [...form.querySelectorAll('[name="violations"]:checked')].map(c => c.value), otherViolation: f.otherViolation.value.trim(),
      summary: f.summary.value.trim(), policy: f.policy.value.trim(), prior: form.querySelector('[name="prior"]:checked')?.value,
      priorText: f.priorText.value.trim(), action: f.action.value.trim(),
    };
    const missing = [!w.name && 'Employee name', !w.date && 'Date of write-up', !w.summary && 'Incident summary', !w.violations.length && 'Type of violation'].filter(Boolean);
    if (missing.length) { toast('Required: ' + missing.join(', '), 'bad'); return; }
    const btn = form.querySelector('[type=submit]'); btn.disabled = true; btn.textContent = 'Creating…';
    try {
      if (f.save.checked) {
        // One Disciplinary Log entry; the first violation type sets its Category.
        w.refId = await store.add('discipline', {
          date: w.date, employee: w.name, category: VIOLATION_TO_CATEGORY[w.violations[0]] || 'Other', action: LEVEL_TO_ACTION[w.level] || w.level,
          description: w.summary, issuedBy: w.manager, signed: 'N',
          notes: [w.action, w.policy && \`Policy / SOP: \${w.policy}\`, w.level === 'Suspension' && \`Suspension: \${w.suspensionDays} day(s)\`, \`Violation: \${w.violations.map(v => (v === 'Other' ? \`Other – \${w.otherViolation}\` : v)).join(', ')}\`].filter(Boolean).join('\\n'),
        });
      }
      const doc = writeUpDocx(w), file = writeUpFileName(w);
      if (f.email.checked) {
        const td = 'style="border:1px solid #c8ced8;padding:4px 8px"', th = 'style="border:1px solid #c8ced8;padding:4px 8px;background:#222b36;color:#fff;text-align:left"';
        const html = \`<div style="font-family:Calibri,Arial,sans-serif;font-size:11pt"><p>Attached is the Employee Corrective Action / Write-Up for \${esc(w.name)}.</p>
          <table style="border-collapse:collapse;font-size:10pt">
          <tr><th \${th}>Employee</th><td \${td}>\${esc(w.name)}</td></tr><tr><th \${th}>Date of write-up</th><td \${td}>\${fmtDate(w.date)}</td></tr>
          <tr><th \${th}>Level</th><td \${td}>\${esc(w.level === 'Suspension' ? \`Suspension – \${w.suspensionDays} day(s)\` : w.level)}</td></tr>
          <tr><th \${th}>Violation</th><td \${td}>\${esc(w.violations.map(v => (v === 'Other' ? \`Other – \${w.otherViolation}\` : v)).join(', '))}</td></tr>
          <tr><th \${th}>Supervisor / manager</th><td \${td}>\${esc(w.manager)}</td></tr>\${w.refId ? \`<tr><th \${th}>Disciplinary Log</th><td \${td}>\${esc(w.refId)}</td></tr>\` : ''}</table>
          <p style="color:#5b6478;font-size:9pt">Confidential — for management and HR only. Created in the Piper Warehouse Operations Dashboard.</p></div>\`;
        const subject = \`Employee Write-Up – \${w.name} – \${us(w.date)}\`;
        const attachments = [[file, new Uint8Array(await doc.arrayBuffer()), DOCX]];
        downloadBlob(\`\${subject.replace(/\\//g, '-')}.eml\`, emlDraft({ subject, html, attachments }));
        await archiveSent({ kind: 'writeup', building: employeeBuilding(w.name), fileDate: w.date, title: \`\${w.name} – \${w.level === 'Suspension' ? \`Suspension (\${w.suspensionDays} day(s))\` : w.level || 'Write-up'}\`, subject, html, attachments, ref: w.refId || \`\${w.name}-\${w.date}\` });
      } else {
        downloadBlob(file, doc);
        await archiveSent({ kind: 'writeup', building: employeeBuilding(w.name), fileDate: w.date, title: \`\${w.name} – \${w.level === 'Suspension' ? \`Suspension (\${w.suspensionDays} day(s))\` : w.level || 'Write-up'}\`, subject: file.replace(/\\.docx$/, ''), html: '', attachments: [[file, new Uint8Array(await doc.arrayBuffer()), DOCX]], ref: w.refId || \`\${w.name}-\${w.date}\` });
      }
      close(); rerender?.();
      toast(\`\${f.save.checked ? \`Write-up saved to the Disciplinary Log\${w.refId ? \` (\${w.refId})\` : ''}. \` : ''}\${f.email.checked ? 'Outlook email created — open the .eml file to review and send.' : 'Word form downloaded.'}\`);
    } catch (err) { console.error(err); toast(err.message, 'bad'); btn.disabled = false; btn.textContent = 'Create write-up'; }
  });
  setTimeout(() => f.name.focus(), 30);
}`]);

